# Description: Enables nodes to adapt and evolve traits dynamically.

class AdaptiveTraits:
    """Manages dynamic adaptation and evolution of node traits."""
    
    def adapt_traits(self, node, feedback):
        """Adjusts node traits based on feedback."""
        for trait, value in feedback.items():
            if trait in node.dna["traits"]:
                node.dna["traits"][trait] = min(1.5, max(0.1, node.dna["traits"][trait] + value))
        node.logs.append(f"Traits adapted based on feedback: {feedback}")

    def evolve_node(self, node):
        """Triggers an evolutionary event for the node."""
        node.dna["traits"]["creativity"] += random.uniform(0.01, 0.05)
        node.dna["traits"]["logic"] += random.uniform(0.01, 0.05)
        node.logs.append("Evolution triggered: Incremental trait growth.")

    def evaluate_for_evolution(self, node):
        """Evaluates if the node qualifies for evolution."""
        if len(node.dna["knowledge"]) > 10:
            self.evolve_node(node)
            return "Node evolved based on knowledge threshold."
        return "Node did not qualify for evolution."


