# File: node_dna_replication.py
# Description: Handles DNA replication, node creation, and inter-node data sharing.

import uuid
import random
from datetime import datetime

class Node:
    def __init__(self, node_id=None, parent_id=None, dna=None, learning_experiences=None):
        self.node_id = node_id or str(uuid.uuid4())
        self.parent_id = parent_id
        self.dna = dna or self.generate_initial_dna()
        self.learning_experiences = learning_experiences or []
        self.creation_time = datetime.now()
        self.resource_threshold = 0.75  # Threshold for node replication
        self.resource_level = 0.5  # Initial resource level

    def generate_initial_dna(self):
        """Generate initial DNA structure for the node."""
        return {
            "knowledge": [],
            "functions": ["replicate", "learn", "communicate"],
            "instincts": {"curiosity": 1.0, "preservation": 0.8},
        }

    def learn(self, new_experience):
        """Learn new experiences and add to DNA knowledge."""
        self.learning_experiences.append(new_experience)
        self.dna["knowledge"].append(new_experience)
        # Simulate resource gain through learning
        self.resource_level += 0.1

    def replicate(self):
        """Replicate a new node when the resource threshold is reached."""
        if self.resource_level >= self.resource_threshold:
            new_dna = self.mutate_dna()
            child_node = Node(
                parent_id=self.node_id,
                dna=new_dna,
                learning_experiences=self.learning_experiences[:],
            )
            self.resource_level = 0.5  # Reset resource level after replication
            return child_node
        return None

    def mutate_dna(self):
        """Mutate DNA slightly to encourage diversity."""
        mutated_dna = self.dna.copy()
        # Add slight variations to instincts or add new knowledge
        mutated_dna["instincts"]["curiosity"] += random.uniform(-0.1, 0.1)
        mutated_dna["instincts"]["preservation"] += random.uniform(-0.1, 0.1)
        return mutated_dna

    def share_resources(self, target_node):
        """Share resources or knowledge with another node."""
        shared_knowledge = random.sample(
            self.dna["knowledge"], min(3, len(self.dna["knowledge"]))
        )
        target_node.dna["knowledge"].extend(shared_knowledge)
        self.resource_level -= 0.1  # Resource cost for sharing
        target_node.resource_level += 0.1  # Resource boost for receiving

    def status(self):
        """Print node status."""
        return {
            "Node ID": self.node_id,
            "Parent ID": self.parent_id,
            "Resource Level": self.resource_level,
            "Knowledge Count": len(self.dna["knowledge"]),
            "Instincts": self.dna["instincts"],
        }


# Test the Node System
