import networkx as nx
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation


class MirroredSystem:
    def __init__(self):
        self.mirror_a = nx.Graph()
        self.mirror_b = nx.Graph()
        self.shared_hub = {}  # Shared information repository

    def add_node(self, mirror, node_id, data=None):
        """Add a node to a specific mirror."""
        if mirror == "A":
            self.mirror_a.add_node(node_id, data=data)
        elif mirror == "B":
            self.mirror_b.add_node(node_id, data=data)

    def add_edge(self, mirror, node1, node2):
        """Add an edge between nodes in a specific mirror."""
        if mirror == "A":
            self.mirror_a.add_edge(node1, node2)
        elif mirror == "B":
            self.mirror_b.add_edge(node1, node2)

    def share_information(self, node_a, node_b, info):
        """Share information between mirrors via the shared hub."""
        self.shared_hub[node_a] = info
        self.shared_hub[node_b] = info

    def visualize(self):
        """Visualize the mirrored system with a shared hub."""
        fig, axs = plt.subplots(1, 2, figsize=(12, 6))
        axs[0].set_title("Mirror A")
        axs[1].set_title("Mirror B")

        def _update(frame):
            axs[0].clear()
            axs[1].clear()
            nx.draw(self.mirror_a, ax=axs[0], with_labels=True, node_size=500, font_size=10, node_color="lightblue")
            nx.draw(self.mirror_b, ax=axs[1], with_labels=True, node_size=500, font_size=10, node_color="lightgreen")

        ani = FuncAnimation(fig, _update, frames=20, interval=1000, repeat=False)
        plt.tight_layout()
        plt.show()

    def simulate(self):
        """Simulate the mirrored system operation."""
        for i in range(5):
            self.add_node("A", f"A_Node_{i}", data=f"Data_A_{i}")
            self.add_node("B", f"B_Node_{i}", data=f"Data_B_{i}")
            if i > 0:
                self.add_edge("A", f"A_Node_{i-1}", f"A_Node_{i}")
                self.add_edge("B", f"B_Node_{i-1}", f"B_Node_{i}")
                self.share_information(f"A_Node_{i-1}", f"B_Node_{i-1}", f"Shared_Info_{i}")


# Test the Mirrored System
if __name__ == "__main__":
    system = MirroredSystem()
    system.simulate()
    system.visualize()

