# File: image_annotation.py
# Description: Annotates images and integrates visual data into node knowledge.

from PIL import Image, ImageDraw, ImageFont
import os
import random

class ImageAnnotator:
    def __init__(self):
        self.annotations = {}  # Store annotations for images

    def annotate_image(self, image_path, annotation_text):
        """Annotates the image with provided text."""
        try:
            # Open the image
            with Image.open(image_path) as img:
                draw = ImageDraw.Draw(img)

                # Choose a font size and position
                font_size = max(10, img.size[0] // 20)
                font = ImageFont.truetype("arial.ttf", font_size)
                text_position = (10, img.size[1] - font_size - 10)

                # Add annotation
                draw.text(text_position, annotation_text, fill="white", font=font)
                
                # Save the annotated image
                annotated_path = f"{os.path.splitext(image_path)[0]}_annotated.png"
                img.save(annotated_path)

                # Store annotation
                self.annotations[annotated_path] = annotation_text

                print(f"Annotated and saved: {annotated_path}")
                return annotated_path
        except Exception as e:
            print(f"Error annotating image: {e}")
            return None

