    node_a.connect_mirror(node_b)

    # Process and mirror data
    for step in range(5):
        print(f"\n--- Step {step} ---")
        new_data = {f"concept_{step}": random.uniform(0, 1)}
        node_a.process_data(new_data)

    # Display the final thoughts of both nodes
    print("\n--- Final Node Thoughts ---")
    node_a.visualize_thoughts()
    node_b.visualize_thoughts()

