# File: mirrored_system_image_processing.py
# Description: Implements a mirrored system for processing images and data in parallel, generating multidimensional insights.

import threading
import numpy as np
import random
from PIL import Image, ImageDraw
import os


class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.image_data = None
        self.textual_data = None
        self.insights = []

    def process_image(self, image_path):
        """Process image data."""
        print(f"Node {self.node_id}: Processing image at {image_path}")
        try:
            image = Image.open(image_path)
            width, height = image.size
            pixels = np.array(image)
            avg_color = np.mean(pixels, axis=(0, 1))
            self.image_data = {
                "dimensions": (width, height),
                "avg_color": avg_color.tolist()
            }
            self.insights.append(f"Processed image dimensions: {width}x{height}, Avg color: {avg_color}")
        except Exception as e:
            print(f"Node {self.node_id}: Error processing image - {e}")

    def process_text(self, text):
        """Process textual data."""
        print(f"Node {self.node_id}: Processing textual data.")
        word_count = len(text.split())
        unique_words = len(set(text.split()))
        self.textual_data = {
            "word_count": word_count,
            "unique_words": unique_words
        }
        self.insights.append(f"Text processed: {word_count} words, {unique_words} unique words.")

    def analyze(self):
        """Generate insights by cross-referencing processed data."""
        if self.image_data and self.textual_data:
            self.insights.append(f"Image and text cross-referenced: Dimensions {self.image_data['dimensions']} mapped to {self.textual_data['word_count']} words.")
        print(f"Node {self.node_id}: Analysis complete. Insights generated.")

    def display_insights(self):
        print(f"\n--- Node {self.node_id} Insights ---")
        for insight in self.insights:
            print(insight)


class MirroredSystem:
    def __init__(self):
        self.nodes = []

    def add_node(self, node):
        self.nodes.append(node)

    def process_parallel(self, image_path, text):
        """Run image and text processing in parallel."""
        threads = []
        for node in self.nodes:
            image_thread = threading.Thread(target=node.process_image, args=(image_path,))
            text_thread = threading.Thread(target=node.process_text, args=(text,))
            threads.extend([image_thread, text_thread])

            image_thread.start()
            text_thread.start()

        for thread in threads:
            thread.join()

    def analyze_all(self):
        """Run analysis on all nodes."""
        for node in self.nodes:
            node.analyze()

    def display_all_insights(self):
        """Display insights for all nodes."""
        for node in self.nodes:
            node.display_insights()


