# File: resource_management.py
# Description: Implements resource management and allocation across nodes in the AI network.

class Resource:
    def __init__(self, name, total_amount):
        self.name = name
        self.total_amount = total_amount
        self.available_amount = total_amount

    def allocate(self, amount):
        """Allocate resources if available."""
        if self.available_amount >= amount:
            self.available_amount -= amount
            return amount
        else:
            print(f"Insufficient {self.name} resources. Only {self.available_amount} available.")
            return 0

    def release(self, amount):
        """Release allocated resources back."""
        self.available_amount += amount
        if self.available_amount > self.total_amount:
            self.available_amount = self.total_amount

    def __str__(self):
        return f"{self.name}: {self.available_amount}/{self.total_amount}"


class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.allocated_resources = {}

    def request_resource(self, resource, amount):
        """Request and allocate a resource."""
        allocated = resource.allocate(amount)
        if allocated > 0:
            self.allocated_resources[resource.name] = self.allocated_resources.get(resource.name, 0) + allocated
            print(f"Node-{self.node_id} allocated {allocated} of {resource.name}.")
        else:
            print(f"Node-{self.node_id} could not allocate {amount} of {resource.name}.")

    def release_resources(self, resource):
        """Release all resources allocated by this node."""
        if resource.name in self.allocated_resources:
            resource.release(self.allocated_resources[resource.name])
            print(f"Node-{self.node_id} released {self.allocated_resources[resource.name]} of {resource.name}.")
            self.allocated_resources[resource.name] = 0

    def __str__(self):
        return f"Node-{self.node_id}: {self.allocated_resources}"


class ResourceManager:
    def __init__(self, resources):
        self.resources = resources
        self.nodes = []

    def add_node(self, node):
        """Add a node to the network."""
        self.nodes.append(node)

    def allocate_resources(self):
        """Allocate resources to all nodes."""
        for node in self.nodes:
            for resource in self.resources:
                node.request_resource(resource, amount=5)  # Example fixed allocation

    def release_all_resources(self):
        """Release all resources from all nodes."""
        for node in self.nodes:
            for resource in self.resources:
                node.release_resources(resource)

    def display_status(self):
        """Display the current resource and node statuses."""
        print("\n--- Resource Status ---")
        for resource in self.resources:
            print(resource)
        print("\n--- Node Status ---")
        for node in self.nodes:
            print(node)


# Example Usage
if __name__ == "__main__":
    # Define resources
    cpu = Resource("CPU", 100)
    memory = Resource("Memory", 200)
    storage = Resource("Storage", 300)

    # Create resource manager and nodes
    resource_manager = ResourceManager(resources=[cpu, memory, storage])
    for i in range(5):
        resource_manager.add_node(Node(node_id=i))

    # Simulate resource allocation and release
    resource_manager.allocate_resources()
    resource_manager.display_status()

    print("\n--- Releasing Resources ---")
    resource_manager.release_all_resources()
    resource_manager.display_status()

