    node_a.link_mirror(node_b)

    # Process in parallel
    thread_a = threading.Thread(target=node_a.process_data, args=(example_task,))
    thread_b = threading.Thread(target=node_b.process_data, args=(example_task,))

    thread_a.start()
    thread_b.start()
    thread_a.join()
    thread_b.join()

    print(node_a)
    print(node_b)

