class ResourceManager:
    def __init__(self):
        self.resource_pool = {}

    def add_resource(self, node_id, resource):
        """Adds a resource to the shared pool."""
        self.resource_pool[node_id] = resource

    def query_resource(self, query_key):
        """Finds the closest matching resource."""
        for node_id, resource in self.resource_pool.items():
            if query_key in resource:
                return node_id, resource
        return None, "Resource not found."

    def distribute_resources(self, requesting_node, query_key):
        """Distributes resources to the requesting node."""
        node_id, resource = self.query_resource(query_key)
        if resource != "Resource not found.":
            print(f"Resource '{query_key}' shared from Node {node_id} to Node {requesting_node}")
        else:
            print(f"No resource matching '{query_key}' found.")

