class SelfReflection:
    def __init__(self, logs):
        self.logs = logs

    def analyze_logs(self):
        """Extracts patterns from logs."""
        patterns = {}
        for log in self.logs:
            for word in log.split():
                patterns[word] = patterns.get(word, 0) + 1
        return patterns

    def suggest_improvements(self):
        """Suggests improvements based on analysis."""
        patterns = self.analyze_logs()
        return [key for key, value in patterns.items() if value > 2]

