import networkx as nx
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation

class NodeVisualizer:
    def __init__(self):
        self.graph = nx.Graph()

    def add_node(self, node_id, attributes):
        """Adds a node with attributes."""
        self.graph.add_node(node_id, **attributes)

    def add_edge(self, node1, node2, weight=1):
        """Adds an edge with weight."""
        self.graph.add_edge(node1, node2, weight=weight)

    def animate(self, interval=1000, steps=20):
        """Animates the network over time."""
        fig, ax = plt.subplots(figsize=(8, 6))

        def update(frame):
            ax.clear()
            pos = nx.spring_layout(self.graph, seed=42)
            nx.draw(
                self.graph,
                pos,
                ax=ax,
                with_labels=True,
                node_size=700,
                font_size=10,
                node_color="skyblue",
                edge_color="gray"
            )
            ax.set_title(f"Network Evolution - Step {frame}")

        ani = FuncAnimation(fig, update, frames=steps, interval=interval, repeat=False)
        plt.show()

