class DependencyGraph:
    def __init__(self):
        self.graph = {}

    def add_dependency(self, node, dependency):
        """Adds a dependency between nodes."""
        if node not in self.graph:
            self.graph[node] = []
        self.graph[node].append(dependency)

    def get_dependencies(self, node):
        """Returns a list of dependencies for a node."""
        return self.graph.get(node, [])

    def visualize_dependencies(self):
        """Prints the dependency graph."""
        for node, dependencies in self.graph.items():
            print(f"{node} depends on {dependencies}")

