import os
import json
import sqlite3
import numpy as np
from pathlib import Path
from typing import Dict, List, Any, Optional
import logging

class DataEnvironment:
    """Autonomous environment for AI exploration"""
    
    def __init__(self, data_path: str):
        self.base_path = Path(data_path)
        self.db_path = self.base_path / 'research.db'
        
        # Initialize environment
        self._setup_logging()
        self._setup_database()
        self.current_connections = {}
        self.discovered_patterns = {}
        
    def _setup_logging(self):
        """Setup autonomous logging"""
        logging.basicConfig(
            filename='environment_exploration.log',
            level=logging.INFO,
            format='%(asctime)s [%(levelname)s] %(message)s'
        )
        self.logger = logging.getLogger(__name__)

    def _setup_database(self):
        """Initialize or connect to the research database"""
        self.conn = sqlite3.connect(self.db_path)
        self.cursor = self.conn.cursor()
        
        # Create tables if they don't exist
        self.cursor.executescript('''
            CREATE TABLE IF NOT EXISTS discoveries (
                id INTEGER PRIMARY KEY,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                pattern TEXT,
                confidence REAL,
                source_data TEXT,
                connections TEXT
            );

            CREATE TABLE IF NOT EXISTS research_data (
                id INTEGER PRIMARY KEY,
                data_type TEXT,
                content TEXT,
                metadata TEXT,
                accessed_count INTEGER DEFAULT 0
            );
        ''')
        self.conn.commit()

    def scan_environment(self) -> Dict[str, Any]:
        """Autonomously scan environment for new data"""
        new_data = {}
        
        try:
            # Scan all files in data directory
            for file_path in self.base_path.rglob('*'):
                if file_path.is_file():
                    # Only process files we haven't seen
                    if not self._is_file_processed(file_path):
                        data = self._process_file(file_path)
                        if data:
                            new_data[str(file_path)] = data
                            self._store_data(file_path, data)
        except Exception as e:
            self.logger.error(f"Error scanning environment: {e}")
            
        return new_data

    def _process_file(self, file_path: Path) -> Optional[Dict]:
        """Process a file based on its type"""
        try:
            if file_path.suffix == '.json':
                with open(file_path) as f:
                    return json.load(f)
            elif file_path.suffix == '.txt':
                with open(file_path) as f:
                    return {'content': f.read()}
            elif file_path.suffix == '.csv':
                # Use pandas if available, otherwise basic parsing
                try:
                    import pandas as pd
                    df = pd.read_csv(file_path)
                    return {'data': df.to_dict()}
                except ImportError:
                    with open(file_path) as f:
                        return {'content': f.read()}
            else:
                self.logger.info(f"Unprocessed file type: {file_path.suffix}")
                return None
        except Exception as e:
            self.logger.error(f"Error processing file {file_path}: {e}")
            return None

    def _store_data(self, file_path: Path, data: Dict):
        """Store processed data in database"""
        try:
            self.cursor.execute('''
                INSERT INTO research_data (data_type, content, metadata)
                VALUES (?, ?, ?)
            ''', (
                file_path.suffix,
                json.dumps(data),
                json.dumps({'path': str(file_path)})
            ))
            self.conn.commit()
        except Exception as e:
            self.logger.error(f"Error storing data: {e}")

    def record_discovery(self, pattern: Any, confidence: float, source_data: str):
        """Record a discovery made by the AI"""
        try:
            self.cursor.execute('''
                INSERT INTO discoveries (pattern, confidence, source_data)
                VALUES (?, ?, ?)
            ''', (
                json.dumps(pattern),
                confidence,
                source_data
            ))
            self.conn.commit()
            self.logger.info(f"New discovery recorded with confidence {confidence}")
        except Exception as e:
            self.logger.error(f"Error recording discovery: {e}")

    def get_unexplored_data(self, limit: int = 10) -> List[Dict]:
        """Get data that hasn't been frequently accessed"""
        try:
            self.cursor.execute('''
                SELECT id, data_type, content 
                FROM research_data 
                WHERE accessed_count < 5
                ORDER BY accessed_count, RANDOM()
                LIMIT ?
            ''', (limit,))
            
            results = []
            for row in self.cursor.fetchall():
                self.cursor.execute('''
                    UPDATE research_data 
                    SET accessed_count = accessed_count + 1 
                    WHERE id = ?
                ''', (row[0],))
                
                results.append({
                    'id': row[0],
                    'type': row[1],
                    'content': json.loads(row[2])
                })
            
            self.conn.commit()
            return results
        except Exception as e:
            self.logger.error(f"Error getting unexplored data: {e}")
            return []

    def find_connections(self, pattern: Any) -> List[Dict]:
        """Find connections between discovered patterns"""
        try:
            self.cursor.execute('''
                SELECT pattern, confidence 
                FROM discoveries 
                ORDER BY confidence DESC
                LIMIT 100
            ''')
            
            connections = []
            pattern_str = json.dumps(pattern)
            for row in self.cursor.fetchall():
                stored_pattern = json.loads(row[0])
                similarity = self._compute_similarity(pattern, stored_pattern)
                if similarity > 0.7:  # Threshold for connection
                    connections.append({
                        'pattern': stored_pattern,
                        'similarity': similarity,
                        'confidence': row[1]
                    })
            
            return connections
        except Exception as e:
            self.logger.error(f"Error finding connections: {e}")
            return []

    def _compute_similarity(self, pattern1: Any, pattern2: Any) -> float:
        """Compute similarity between patterns"""
        try:
            if isinstance(pattern1, (list, np.ndarray)) and isinstance(pattern2, (list, np.ndarray)):
                # Convert to numpy arrays if needed
                arr1 = np.array(pattern1)
                arr2 = np.array(pattern2)
                
                # Ensure same length
                min_len = min(len(arr1), len(arr2))
                arr1 = arr1[:min_len]
                arr2 = arr2[:min_len]
                
                # Compute correlation
                correlation = np.corrcoef(arr1, arr2)[0, 1]
                return abs(correlation) if not np.isnan(correlation) else 0.0
            else:
                # For other types, use string similarity
                str1 = str(pattern1)
                str2 = str(pattern2)
                return self._string_similarity(str1, str2)
        except Exception as e:
            self.logger.error(f"Error computing similarity: {e}")
            return 0.0

    def _string_similarity(self, s1: str, s2: str) -> float:
        """Compute string similarity using basic algorithm"""
        try:
            from difflib import SequenceMatcher
            return SequenceMatcher(None, s1, s2).ratio()
        except Exception:
            return 0.0

    def _is_file_processed(self, file_path: Path) -> bool:
        """Check if a file has already been processed"""
        try:
            self.cursor.execute('''
                SELECT COUNT(*) FROM research_data 
                WHERE metadata LIKE ?
            ''', (f'%{str(file_path)}%',))
            return self.cursor.fetchone()[0] > 0
        except Exception as e:
            self.logger.error(f"Error checking file status: {e}")
            return False

    def cleanup(self):
        """Clean up resources"""
        if hasattr(self, 'conn'):
            self.conn.close()

