from dataclasses import dataclass, field
from typing import Dict, Set, List, Optional
import numpy as np
from collections import defaultdict
import time

@dataclass
class CoreRules:
    """Fundamental rules that govern autonomous growth - like laws of physics"""
    energy_decay_rate: float = 0.01  # Natural energy loss over time
    energy_transfer_efficiency: float = 0.85  # Energy lost in transfers
    memory_fusion_threshold: float = 0.7  # When memories combine
    connection_decay_rate: float = 0.05  # Natural connection weakening
    minimum_survival_energy: float = 1.0  # Energy needed to exist
    
    # These values can mutate slightly when nodes split
    def mutate(self) -> 'CoreRules':
        """Allow slight mutations in rules for evolutionary adaptation"""
        return CoreRules(
            energy_decay_rate=max(0.001, self.energy_decay_rate * np.random.normal(1, 0.1)),
            energy_transfer_efficiency=min(0.99, self.energy_transfer_efficiency * np.random.normal(1, 0.1)),
            memory_fusion_threshold=max(0.5, self.memory_fusion_threshold * np.random.normal(1, 0.1)),
            connection_decay_rate=max(0.01, self.connection_decay_rate * np.random.normal(1, 0.1)),
            minimum_survival_energy=max(0.5, self.minimum_survival_energy * np.random.normal(1, 0.1))
        )

class Memory:
    """Organic memory structure that can grow, combine, and evolve"""
    def __init__(self, initial_content: any):
        self.content = initial_content
        self.connections: Dict[str, float] = {}
        self.strength = 1.0
        self.creation_time = time.time()
        self.access_count = 0
        self.last_access = time.time()
        
    def access(self):
        """Memory access strengthens it"""
        self.access_count += 1
        current_time = time.time()
        time_factor = 1.0 / (1.0 + (current_time - self.last_access))
        self.strength = min(1.0, self.strength + (0.1 * time_factor))
        self.last_access = current_time
        
    def decay(self, rate: float):
        """Natural memory decay over time"""
        current_time = time.time()
        time_passed = current_time - self.last_access
        self.strength *= (1.0 - (rate * time_passed))
        return self.strength > 0.1  # Return False if memory too weak

    def can_merge(self, other: 'Memory', threshold: float) -> bool:
        """Check if memories can be merged based on connections"""
        return any(
            other_id in self.connections 
            and self.connections[other_id] > threshold
            for other_id in other.connections
        )

class AutonomousNode:
    """Base node class that follows core rules but develops autonomously"""
    def __init__(self, core_rules: CoreRules):
        self.rules = core_rules
        self.energy = 10.0
        self.memories: Dict[str, Memory] = {}
        self.connections: Dict[str, float] = {}
        self.specialization = defaultdict(float)
        
    def update(self) -> bool:
        """Natural update cycle - returns False if node should die"""
        # Natural energy decay
        self.energy *= (1.0 - self.rules.energy_decay_rate)
        
        # Memory maintenance
        self._maintain_memories()
        
        # Connection decay
        self._decay_connections()
        
        # Return survival status
        return self.energy > self.rules.minimum_survival_energy

    def _maintain_memories(self):
        """Maintain memory system autonomously"""
        # Decay memories
        self.memories = {
            mid: mem for mid, mem in self.memories.items()
            if mem.decay(self.rules.energy_decay_rate)
        }
        
        # Look for potential memory merges
        self._merge_memories()
        
    def _merge_memories(self):
        """Allow memories to merge organically"""
        merged = set()
        for mid1, mem1 in self.memories.items():
            if mid1 in merged:
                continue
            for mid2, mem2 in self.memories.items():
                if mid2 in merged or mid1 == mid2:
                    continue
                if mem1.can_merge(mem2, self.rules.memory_fusion_threshold):
                    self._perform_memory_merge(mem1, mem2)
                    merged.add(mid2)
                    
    def _perform_memory_merge(self, mem1: Memory, mem2: Memory):
        """Merge two memories"""
        # This should be implemented by specific node types
        pass

    def _decay_connections(self):
        """Natural decay of connections"""
        self.connections = {
            cid: strength * (1.0 - self.rules.connection_decay_rate)
            for cid, strength in self.connections.items()
            if strength * (1.0 - self.rules.connection_decay_rate) > 0.1
        }

class TextNode(AutonomousNode):
    """Node specializing in text processing"""
    def process_text(self, text: str) -> Set[str]:
        """Process text and identify nouns organically"""
        # Energy cost proportional to text length
        energy_cost = len(text) * 0.001
        if self.energy < energy_cost:
            return set()
            
        self.energy -= energy_cost
        
        # Extract potential nouns (simplified)
        words = text.split()
        potential_nouns = {
            word for word in words 
            if word[0].isupper() or word in self.memories
        }
        
        # Create or strengthen memories
        for noun in potential_nouns:
            if noun not in self.memories:
                self.memories[noun] = Memory(noun)
            else:
                self.memories[noun].access()
                
        return potential_nouns

    def _perform_memory_merge(self, mem1: Memory, mem2: Memory):
        """Merge text memories based on context"""
        # Combine connections
        combined_connections = defaultdict(float)
        for conn_id, strength in mem1.connections.items():
            combined_connections[conn_id] += strength
        for conn_id, strength in mem2.connections.items():
            combined_connections[conn_id] += strength
            
        # Create new memory
        new_mem = Memory(f"{mem1.content}_{mem2.content}")
        new_mem.connections = dict(combined_connections)
        new_mem.strength = max(mem1.strength, mem2.strength)
        
        # Replace old memories
        self.memories[new_mem.content] = new_mem
        del self.memories[mem1.content]
        del self.memories[mem2.content]

class VisualNode(AutonomousNode):
    """Node specializing in visual processing"""
    def process_image(self, image_data: np.ndarray, associated_text: Optional[str] = None) -> Dict:
        """Process image data autonomously"""
        # Energy cost proportional to image size
        energy_cost = image_data.size * 0.0001
        if self.energy < energy_cost:
            return {}
            
        self.energy -= energy_cost
        
        # Extract features (simplified)
        features = np.mean(image_data, axis=(0, 1))
        
        # Create memory signature
        signature = str(hash(features.tobytes()))
        
        if signature not in self.memories:
            self.memories[signature] = Memory({
                'features': features,
                'text': associated_text
            })
        else:
            self.memories[signature].access()
            if associated_text:
                self.memories[signature].content['text'] = associated_text
                
        return {
            'signature': signature,
            'confidence': self.memories[signature].strength
        }

    def _perform_memory_merge(self, mem1: Memory, mem2: Memory):
        """Merge visual memories based on feature similarity"""
        # Combine features
        combined_features = (
            mem1.content['features'] + mem2.content['features']
        ) / 2
        
        # Create new memory
        new_signature = str(hash(combined_features.tobytes()))
        new_mem = Memory({
            'features': combined_features,
            'text': f"{mem1.content['text']}_{mem2.content['text']}"
            if mem1.content['text'] and mem2.content['text']
            else mem1.content['text'] or mem2.content['text']
        })
        
        # Combine connections
        new_mem.connections = {
            k: (mem1.connections.get(k, 0) + mem2.connections.get(k, 0)) / 2
            for k in set(mem1.connections) | set(mem2.connections)
        }
        
        # Replace old memories
        self.memories[new_signature] = new_mem
        del self.memories[mem1.content]
        del self.memories[mem2.content]

class AutonomousNetwork:
    """Network that grows and develops autonomously"""
    def __init__(self):
        self.core_rules = CoreRules()
        self.text_nodes: Dict[str, TextNode] = {}
        self.visual_nodes: Dict[str, VisualNode] = {}
        self.global_energy = 1000.0
        
    def process_input(self, text: str, images: Dict[str, np.ndarray]):
        """Process input without direct control"""
        # Distribute energy
        self._distribute_energy()
        
        # Let nodes process naturally
        text_results = self._process_text(text)
        visual_results = self._process_images(images, text_results)
        
        # Allow natural growth/death
        self._natural_cycle()
        
    def _distribute_energy(self):
        """Distribute energy based on node activity"""
        if not self.text_nodes and not self.visual_nodes:
            # Create initial nodes if none exist
            self.text_nodes['initial'] = TextNode(self.core_rules)
            self.visual_nodes['initial'] = VisualNode(self.core_rules)
            return
            
        # Natural energy distribution
        active_nodes = len(self.text_nodes) + len(self.visual_nodes)
        if active_nodes > 0:
            energy_per_node = min(
                10.0,
                (self.global_energy * 0.1) / active_nodes
            )
            
            for node in list(self.text_nodes.values()) + list(self.visual_nodes.values()):
                if self.global_energy > energy_per_node:
                    self.global_energy -= energy_per_node
                    node.energy += energy_per_node

    def _natural_cycle(self):
        """Allow network to evolve naturally"""
        # Update nodes
        for nodes in [self.text_nodes, self.visual_nodes]:
            for node_id, node in list(nodes.items()):
                if not node.update():  # Node dies
                    del nodes[node_id]
                elif node.energy > 20.0:  # Node can split
                    self._handle_split(node, nodes)

    def _handle_split(self, node: AutonomousNode, nodes: Dict[str, AutonomousNode]):
        """Handle node splitting"""
        # Create new node with mutated rules
        new_node = type(node)(node.rules.mutate())
        
        # Split energy
        energy_split = node.energy * 0.4  # Parent keeps more energy
        node.energy -= energy_split
        new_node.energy = energy_split
        
        # Add to network
        nodes[str(time.time())] = new_node
