from core_laws import CoreLaws
from text_node import TextNode
from visual_node import VisualNode
from typing import Dict
import numpy as np

class AutonomousNetwork:
    """Network that grows and develops autonomously"""
    def __init__(self):
        self.core_laws = CoreLaws()
        self.text_nodes: Dict[str, TextNode] = {}
        self.visual_nodes: Dict[str, VisualNode] = {}
        self.global_energy = 1000.0

    def process_input(self, text: str, images: Dict[str, np.ndarray]):
        """Process input without direct control"""
        # Distribute energy
        self._distribute_energy()

        # Let nodes process naturally
        text_results = self._process_text(text)
        visual_results = self._process_images(images, text_results)

        # Allow natural growth/death
        self._natural_cycle()

    def _distribute_energy(self):
        """Distribute energy based on node activity"""
        if not self.text_nodes and not self.visual_nodes:
            # Create initial nodes if none exist
            self._create_initial_nodes()
            return

        # Natural energy distribution
        active_nodes = len(self.text_nodes) + len(self.visual_nodes)
        if active_nodes > 0:
            energy_per_node = min(
                10.0,
                (self.global_energy * 0.1) / active_nodes
            )

            for node in list(self.text_nodes.values()) + list(self.visual_nodes.values()):
                if self.global_energy > energy_per_node:
                    self.global_energy -= energy_per_node
                    node.energy += energy_per_node

    def _create_initial_nodes(self):
        """Create initial nodes for text and visual processing"""
        text_node = TextNode(self.core_laws)
        self.text_nodes[text_node.id] = text_node

        visual_node = VisualNode(self.core_laws)
        self.visual_nodes[visual_node.id] = visual_node

    def _process_text(self, text: str) -> Dict:
        """Process text through text nodes"""
        results = {}
        for node in self.text_nodes.values():
            if node.energy > 0:
                nouns = node.process_text(text)
                results[node.id] = nouns
        return results

    def _process_images(self, images: Dict[str, np.ndarray], text_results: Dict) -> Dict:
        """Process images through visual nodes"""
        results = {}
        for node in self.visual_nodes.values():
            if node.energy > 0:
                for image_name, image_data in images.items():
                    # Associate images with text if possible
                    associated_text = None
                    for nouns in text_results.values():
                        if image_name in nouns:
                            associated_text = image_name
                            break
                    visual_result = node.process_image(image_data, associated_text)
                    results[node.id] = visual_result
        return results

    def _natural_cycle(self):
        """Allow network to evolve naturally"""
        # Update text nodes
        for node_id, node in list(self.text_nodes.items()):
            alive = node.update()
            if not alive:
                del self.text_nodes[node_id]
            elif node.can_split():
                new_node = TextNode(core_laws=self.core_laws.mutate())
                self.text_nodes[new_node.id] = new_node

        # Update visual nodes
        for node_id, node in list(self.visual_nodes.items()):
            alive = node.update()
            if not alive:
                del self.visual_nodes[node_id]
            elif node.can_split():
                new_node = VisualNode(core_laws=self.core_laws.mutate())
                self.visual_nodes[new_node.id] = new_node

