import uuid
import random

class AutonomousNode:
    """Core autonomous node with instincts, traits, and self-directed growth."""

    def __init__(self):
        self.node_id = str(uuid.uuid4())
        self.dna = {
            "instincts": self._initialize_instincts(),
            "traits": self._initialize_traits(),
            "knowledge": [],
            "self_generated_goals": [],
        }
        self.resources = {"energy": 100, "memory": 100}
        self.logs = []

    def _initialize_instincts(self):
        """Define primal instincts for exploration and preservation."""
        return {
            "curiosity": random.uniform(0.8, 1.0),
            "preservation": random.uniform(0.6, 0.8),
        }

    def _initialize_traits(self):
        """Define dynamic traits for creativity and logic."""
        return {
            "creativity": random.uniform(0.5, 1.0),
            "logic": random.uniform(0.5, 1.0),
        }

    def perceive(self, input_data):
        """Process input data and integrate it into the node's knowledge base."""
        if len(input_data) < 3:  # Reject invalid inputs
            self.logs.append(f"Invalid input ignored: {input_data}")
            return
        self.logs.append(f"Perceived: {input_data}")
        self.dna["knowledge"].append(input_data)

    def decide_action(self):
        """Decide an action based on instincts and resource availability."""
        if self.resources["energy"] > 50:
            return "explore"
        elif self.resources["energy"] <= 50:
            return "preserve"
        else:
            return "reflect"

    def execute_action(self, action):
        """Execute the chosen action."""
        if action == "explore":
            self.resources["energy"] -= 10
            self.logs.append("Explored new knowledge.")
        elif action == "preserve":
            self.resources["energy"] += 5
            self.logs.append("Preserved resources.")
        elif action == "reflect":
            self.logs.append("Reflected on existing knowledge.")

    def grow(self):
        """Trigger growth based on accumulated knowledge."""
        if len(self.dna["knowledge"]) > 5:
            self.dna["traits"]["creativity"] += random.uniform(0.01, 0.05)
            self.dna["traits"]["logic"] += random.uniform(0.01, 0.05)
            self.logs.append("Growth triggered: Traits improved through learning.")

    def status(self):
        """Display the current status of the node."""
        return {
            "Node ID": self.node_id,
            "Instincts": self.dna["instincts"],
            "Traits": self.dna["traits"],
            "Knowledge Count": len(self.dna["knowledge"]),
            "Resources": self.resources,
            "Logs": self.logs[-5:],  # Last 5 logs
        }

class AutonomousReflection:
    def __init__(self):
        self.reflections = []

    def generate_insight(self, node):
        """Generate insights from node's knowledge."""
        if node.knowledge:
            insight = f"Node {node.id} has {len(node.knowledge)} knowledge entries."
            self.reflections.append(insight)
            return insight
        return "No knowledge available for reflection."

    def reflect_all(self, nodes):
        """Reflect on all nodes."""
        insights = [self.generate_insight(node) for node in nodes]
        return insights
