import os
from pathlib import Path
from typing import Dict, Any

class Config:
    """System configuration management."""
    
    def __init__(self):
        self.base_dir = Path(__file__).resolve().parent.parent
        self.load_config()
        
    def load_config(self):
        """Load configuration from environment variables with defaults."""
        self.config = {
            'DEBUG': os.getenv('DEBUG', 'False').lower() == 'true',
            'FLASK_ENV': os.getenv('FLASK_ENV', 'production'),
            'PORT': int(os.getenv('PORT', 5000)),
            'HOST': os.getenv('HOST', '0.0.0.0'),
            'LOG_LEVEL': os.getenv('LOG_LEVEL', 'INFO'),
            'DATA_DIR': str(self.base_dir / 'data'),
            'MODELS_DIR': str(self.base_dir / 'models'),
            'MAX_NODES': int(os.getenv('MAX_NODES', 10)),
            'MEMORY_LIMIT': os.getenv('MEMORY_LIMIT', '8G'),
            'USE_GPU': os.getenv('USE_GPU', 'True').lower() == 'true',
            'CHATBOT_MODEL': os.getenv('CHATBOT_MODEL', 'microsoft/DialoGPT-medium'),
            'SECRET_KEY': os.getenv('SECRET_KEY', 'your-secret-key-here')
        }
        
    def get(self, key: str, default: Any = None) -> Any:
        """Get configuration value."""
        return self.config.get(key, default)
        
    def to_dict(self) -> Dict[str, Any]:
        """Get configuration as dictionary."""
        return self.config.copy()# config/config.py

