class DualNetworkSystem:
    """System managing both text and visual networks"""
    def __init__(self, growth_laws: GrowthLaws = None):
        self.laws = growth_laws or GrowthLaws()
        self.text_nodes: Dict[str, TextNode] = {}
        self.visual_nodes: Dict[str, VisualNode] = {}
        self.global_memory: Dict[str, Dict] = {}
        
    def process_input(self, text: str, images: Dict[str, np.ndarray]):
        """Process text and associated images"""
        # Process text
        text_results = self._process_text(text)
        
        # Process images for identified nouns
        visual_results = self._process_images(text_results, images)
        
        # Update global memory
        self._update_global_memory(text_results, visual_results)
        
        # Handle node growth and specialization
        self._manage_network_growth()

    def _process_text(self, text: str) -> Dict[str, Dict]:
        """Process text through text nodes"""
        results = {}
        for node in self.text_nodes.values():
            if node.energy > 0:
                nouns = node.process_text(text)
                for noun, confidence in nouns.items():
                    if noun not in results or confidence > results[noun]['confidence']:
                        results[noun] = {
                            'confidence': confidence,
                            'node_id': node.id
                        }
        return results

    def _process_images(self, text_results: Dict[str, Dict], 
                       images: Dict[str, np.ndarray]) -> Dict[str, Dict]:
        """Process images through visual nodes"""
        results = {}
        for noun, text_info in text_results.items():
            if noun in images:
                for node in self.visual_nodes.values():
                    if node.energy > 0:
                        visual_result = node.process_image(images[noun], noun)
                        if noun in visual_result:
                            if (noun not in results or 
                                visual_result[noun] > results[noun]['confidence']):
                                results[noun] = {
                                    'confidence': visual_result[noun],
                                    'node_id': node.id
                                }
        return results

    def _update_global_memory(self, text_results: Dict[str, Dict], 
                            visual_results: Dict[str, Dict]):
        """Update global memory with processed results"""
        for noun in set(text_results.keys()) | set(visual_results.keys()):
            if noun not in self.global_memory:
                self.global_memory[noun] = {
                    'text_confidence': [],
                    'visual_confidence': [],
                    'connections': defaultdict(float)
                }
                
            # Update confidences
            if noun in text_results:
                self.global_memory[noun]['text_confidence'].append(
                    text_results[noun]['confidence']
                )
            if noun in visual_results:
                self.global_memory[noun]['visual_confidence'].append(
                    visual_results[noun]['confidence']
                )
                
            # Update connections
            for other_noun in self.global_memory:
                if other_noun != noun:
                    connection_strength = self._calculate_connection_strength(
                        noun, other_noun, text_results, visual_results
                    )
                    self.global_memory[noun]['connections'][other_noun] = connection_strength

    def _calculate_connection_strength(self, noun1: str, noun2: str,
                                    text_results: Dict[str, Dict],
                                    visual_results: Dict[str, Dict]) -> float:
        """Calculate connection strength between two nouns"""
        strength = 0.0
        
        # Text-based connection
        if noun1 in text_results and noun2 in text_results:
            strength += min(text_results[noun1]['confidence'],
                          text_results[noun2]['confidence'])
            
        # Visual-based connection
        if noun1 in visual_results and noun2 in visual_results:
            strength += min(visual_results[noun1]['confidence'],
                          visual_results[noun2]['confidence'])
            
        return strength / 2

    def _manage_network_growth(self):
        """Manage growth and specialization of both networks"""
        # Check text nodes for splitting
        for node_id, node in list(self.text_nodes.items()):
            if node.can_split():
                new_node = self._create_text_node(parent_node=node)
                self.text_nodes[new_node.id] = new_node
                
        # Check visual nodes for splitting
        for node_id, node in list(self.visual_nodes.items()):
            if node.can_split():
                new_node = self._create_visual_node(parent_node=node)
                self.visual_nodes[new_node.id] = new_node
                
        # Remove depleted nodes
        self._clean_up_nodes()

    def _create_text_node(self, parent_node: Optional[TextNode] = None) -> TextNode:
        """Create new text node, optionally inheriting from parent"""
        genes = parent_node.genes.mutate() if parent_node else NodeGenes.create_initial()
        return TextNode(genes=genes)

    def _create_visual_node(self, parent_node: Optional[VisualNode] = None) -> VisualNode:
        """Create new visual node, optionally inheriting from parent"""
        genes = parent_node.genes.mutate() if parent_node else NodeGenes.create_initial()
        return VisualNode(genes=genes)

    def _clean_up_nodes(self):
        """Remove depleted nodes"""
        # Remove text nodes
        self.text_nodes = {
            node_id: node 
            for node_id, node in self.text_nodes.items()
            if node.energy > 0
        }
        
        # Remove visual nodes
        self.visual_nodes = {
            node_id: node
            for node_id, node in self.visual_nodes.items()
            if node.energy > 0
        }
