import matplotlib.pyplot as plt
import networkx as nx
import logging
from typing import Dict

# Configure logging
logging.basicConfig(
    filename="energy_flow_graph.log",
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

class EnergyFlowGraph:
    """
    Visualizes the energy flow among nodes in the Kaleidoscope AI system.
    """

    def __init__(self):
        self.graph = nx.DiGraph()

    def update_graph(self, energy_flow: Dict[str, Dict[str, float]]) -> None:
        """
        Updates the graph with new energy flow data.

        Args:
            energy_flow (Dict[str, Dict[str, float]]):
                A dictionary where keys are source nodes, and values are dictionaries
                of target nodes and energy amounts.

        Returns:
            None
        """
        logging.info("Updating energy flow graph...")

        self.graph.clear()

        for source, targets in energy_flow.items():
            for target, energy in targets.items():
                self.graph.add_edge(source, target, weight=energy)
                logging.info(f"Added edge: {source} -> {target} with energy {energy}")

    def visualize(self, title: str = "Energy Flow Graph", save_path: str = None) -> None:
        """
        Visualizes the energy flow graph with optional save functionality.

        Args:
            title (str): Title for the visualization.
            save_path (str): File path to save the visualization (optional).

        Returns:
            None
        """
        logging.info("Visualizing energy flow graph...")

        plt.figure(figsize=(10, 8))
        pos = nx.spring_layout(self.graph)

        # Draw nodes and edges
        nx.draw(
            self.graph, pos, with_labels=True, node_size=800,
            node_color="lightgreen", font_size=10, edge_color="gray"
        )

        # Draw edge labels for energy values
        edge_labels = nx.get_edge_attributes(self.graph, 'weight')
        nx.draw_networkx_edge_labels(self.graph, pos, edge_labels=edge_labels)

        plt.title(title)

        if save_path:
            plt.savefig(save_path)
            logging.info(f"Energy flow graph saved to {save_path}")
        else:
            plt.show()

    def clear_graph(self) -> None:
        """
        Clears the energy flow graph for fresh visualization.

        Returns:
            None
        """
        logging.info("Clearing energy flow graph...")
        self.graph.clear()

if __name__ == "__main__":
    energy_graph = EnergyFlowGraph()

    # Example energy flow data
    energy_flow = {
        "Node_1": {"Node_2": 10.5, "Node_3": 5.0},
        "Node_2": {"Node_3": 8.0, "Node_4": 3.2},
        "Node_4": {"Node_1": 4.0}
    }

    energy_graph.update_graph(energy_flow)
    energy_graph.visualize(title="Example Energy Flow")
    energy_graph.clear_graph()

