import matplotlib.pyplot as plt

class EnhancedMonitoringDashboard(MonitoringDashboard):
    """Adds visualization capabilities to the monitoring dashboard."""

    def visualize_resource_usage(self, network):
        """Generates a resource usage chart for the network."""
        node_ids = [node.node_id[:5] for node in network.nodes]  # Shortened IDs
        energy_levels = [node.resources["energy"] for node in network.nodes]
        memory_levels = [node.resources["memory"] for node in network.nodes]

        plt.figure(figsize=(10, 5))
        plt.bar(node_ids, energy_levels, alpha=0.6, label='Energy')
        plt.bar(node_ids, memory_levels, alpha=0.6, label='Memory', bottom=energy_levels)
        plt.xlabel("Node IDs")
        plt.ylabel("Resource Levels")
        plt.title("Resource Usage Across Nodes")
        plt.legend()
        plt.show()

    def visualize_task_completion(self, network):
        """Generates a pie chart of task completions across nodes."""
        task_counts = [len(node.dna["knowledge"]) for node in network.nodes]
        labels = [node.node_id[:5] for node in network.nodes]

        plt.figure(figsize=(7, 7))
        plt.pie(task_counts, labels=labels, autopct='%1.1f%%', startangle=140)
        plt.title("Task Completion Distribution")
        plt.show()


