class CollectiveLearning:
    def __init__(self):
        self.shared_knowledge = {}

    def share_knowledge(self, node_knowledge):
        # Share knowledge from one node to the collective pool
        for key, value in node_knowledge.items():
            if key in self.shared_knowledge:
                self.shared_knowledge[key] = max(self.shared_knowledge[key], value)
            else:
                self.shared_knowledge[key] = value

    def retrieve_knowledge(self, key):
        # Retrieve knowledge from the collective pool
        return self.shared_knowledge.get(key, None)
