import random

class SimulatedEnvironment:
    """Represents a dynamic environment where nodes interact and learn."""
    
    def __init__(self, name="Default Environment"):
        self.name = name
        self.conditions = {"temperature": 25, "light": 50, "resources": 100}
        self.event_log = []

    def generate_event(self):
        """Simulates an environmental event."""
        event_type = random.choice(["resource_gain", "resource_loss", "knowledge_discovery"])
        magnitude = random.randint(1, 20)
        
        if event_type == "resource_gain":
            self.conditions["resources"] += magnitude
            self.event_log.append(f"Resource gain: {magnitude}")
        elif event_type == "resource_loss":
            self.conditions["resources"] = max(0, self.conditions["resources"] - magnitude)
            self.event_log.append(f"Resource loss: {magnitude}")
        elif event_type == "knowledge_discovery":
            discovery = f"Discovery_{random.randint(100, 999)}"
            self.event_log.append(f"Knowledge discovery: {discovery}")
            return discovery
        return None

    def simulate_interactions(self, node):
        """Simulates interactions between the environment and a node."""
        event = self.generate_event()
        if event:
            node.perceive(event)

    def status(self):
        """Displays the current state of the environment."""
        return {
            "Environment Name": self.name,
            "Conditions": self.conditions,
            "Event Log": self.event_log[-10:],  # Show the last 10 events
        }


