import logging
import traceback
from typing import Dict, Any, Optional
from functools import wraps

class SystemError(Exception):
    """Base error for system exceptions."""
    pass

class NodeError(SystemError):
    """Error related to node operations."""
    pass

class ProcessingError(SystemError):
    """Error related to data processing."""
    pass

class ChatbotError(SystemError):
    """Error related to chatbot operations."""
    pass

def handle_errors(logger: Optional[logging.Logger] = None):
    """Decorator for error handling."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                error_info = {
                    'error_type': type(e).__name__,
                    'error_message': str(e),
                    'traceback': traceback.format_exc()
                }
                
                if logger:
                    logger.error(f"Error in {func.__name__}: {str(e)}\n{traceback.format_exc()}")
                
                raise SystemError(error_info)
        return wrapper
    return decorator

def format_error_response(error: Exception) -> Dict[str, Any]:
    """Format error for API response."""
    return {
        'error': {
            'type': type(error).__name__,
            'message': str(error),
            'details': getattr(error, 'details', None)
        }
    }

