# Description: Implements error-handling mechanisms for nodes and networks.

class ErrorHandler:
    """Manages and resolves errors within nodes and networks."""

    def __init__(self):
        self.error_log = []

    def handle_node_error(self, node, error):
        """Handles errors specific to a node."""
        resolution = f"Node {node.node_id} error resolved: {error}."
        self.error_log.append(f"Node Error: {node.node_id} -> {error}")
        node.logs.append(resolution)
        return resolution

    def handle_network_error(self, network, error):
        """Handles errors across the network."""
        resolution = f"Network error resolved: {error}."
        self.error_log.append(f"Network Error: {error}")
        for node in network.nodes:
            node.logs.append(resolution)
        return resolution

    def status(self):
        """Returns the status of the error-handling system."""
        return {
            "Error Log": self.error_log[-10:]  # Last 10 errors
        }


