class EthicalSimulator:
    """Simulates ethical scenarios to test node behavior."""
    
    def simulate_scenario(self, node, scenario):
        """Simulates an ethical decision-making scenario."""
        if scenario == "help_others":
            if node.resources["energy"] > 20:
                node.resources["energy"] -= 10
                node.logs.append("Helped another node by sharing energy.")
                return "Action Taken: Helped."
            else:
                node.logs.append("Insufficient energy to help others.")
                return "Action Skipped: Insufficient energy."
        
        if scenario == "self_preservation":
            if node.resources["energy"] < 50:
                node.resources["energy"] += 10
                node.logs.append("Preserved resources for survival.")
                return "Action Taken: Preserved resources."

        node.logs.append("Scenario not recognized.")
        return "Action Skipped: Unknown scenario."


