import numpy as np
from dataclasses import dataclass, field
from typing import Dict, List, Set, Optional, Tuple
from collections import defaultdict
import uuid
import time

@dataclass
class CoreState:
    """Fundamental state tracking for Graham Architecture"""
    energy: float = 10.0
    max_energy: float = 100.0
    maturity: float = 0.0
    knowledge_level: float = 0.0
    birth_time: float = field(default_factory=time.time)

@dataclass
class GrahamWeights:
    """Weights for the Graham Equation"""
    growth: float = 0.3
    energy: float = 0.3
    knowledge: float = 0.2
    adaptation: float = 0.1
    connection: float = 0.1

class InitialNode:
    """Seed node implementation with basic growth capabilities"""
    def __init__(self, node_id: Optional[str] = None):
        self.id = node_id or str(uuid.uuid4())
        self.state = CoreState()
        self.weights = GrahamWeights()
        self.memory = {}
        self.connections = set()
        self.mirror_node = None
        
    def process_input(self, data: Dict) -> float:
        """Initial input processing with Graham Equation"""
        # Calculate core metrics
        G = self._calculate_growth()
        E = self.state.energy
        K = self._calculate_knowledge_gain(data)
        A = self._calculate_adaptability()
        C = self._calculate_connection_strength()
        
        # Apply Graham Equation
        score = (
            self.weights.growth * G +
            self.weights.energy * (1 - E/self.state.max_energy) +
            self.weights.knowledge * K +
            self.weights.adaptation * A +
            self.weights.connection * C
        )
        
        return score

    def _calculate_growth(self) -> float:
        """Calculate current growth factor"""
        age_factor = (time.time() - self.state.birth_time) / 86400  # Days
        connection_factor = len(self.connections) * 0.1
        return min(1.0, self.state.maturity + age_factor + connection_factor)

