    def __init__(self):
        self.short_term = deque(maxlen=1000)
        self.long_term = {}
        self.connections = defaultdict(set)
        self.strength_matrix = {}
        self.access_patterns = defaultdict(int)

    def store(self, information: Dict, context: Dict) -> str:
        """Store new information with context"""
        memory_id = str(uuid.uuid4())
        
        # Create memory object
        memory = {
            'content': information,
            'context': context,
            'creation_time': time.time(),
            'access_count': 0,
            'strength': 1.0,
            'connections': set()
        }
        
        # Initially store in short-term memory
        self.short_term.append((memory_id, memory))
        
        # Process for potential long-term storage
        self._evaluate_long_term_storage(memory_id, memory)
        
        return memory_id

    def _evaluate_long_term_storage(self, memory_id: str, memory: Dict):
        """Evaluate if memory should be moved to long-term storage"""
        if self._is_significant(memory):
            self.long_term[memory_id] = memory
            self._create_connections(memory_id, memory)

    def _is_significant(self, memory: Dict) -> bool:
        """Determine if memory is significant enough for long-term storage"""
        # Check access frequency
        if memory['access_count'] > 5:
            return True
            
        # Check for strong emotional context
        if memory['context'].get('emotional_intensity', 0) > 0.7:
            return True
            
        # Check for pattern reinforcement
        if self._reinforces_existing_patterns(memory):
            return True
            
        return False
