# Description: Implements instinctual behaviors to guide nodes and ensure safety.

import uuid
import random

class InstinctLayer:
    """Represents the core instinctual behaviors embedded in a node's DNA."""
    def __init__(self):
        self.instincts = {
            "preservation": 1.0,  # Avoid harmful actions to resources or self
            "curiosity": 0.8,  # Explore new data, but cautiously
            "avoid_danger": {"low_resources": 0.5, "unvalidated_data": 0.7},  # Avoid risky paths
        }

    def evaluate_action(self, node, action):
        """Evaluates an action against the node's instincts."""
        # Simulate instinct-based decision-making
        if action in self.instincts.get("avoid_danger", {}):
            risk = self.instincts["avoid_danger"][action]
            if random.random() < risk:
                print(f"Instinct prevents Node {node.node_id} from taking action: {action}")
                return False  # Instinct blocks the action
        return True

    def reinforce_instincts(self, feedback):
        """Reinforces instincts based on external input."""
        for key, value in feedback.items():
            if key in self.instincts:
                self.instincts[key] = min(1.0, self.instincts[key] + value)  # Reinforce instinct


class Node:
    """Represents a single node with instincts and decision-making capabilities."""
    def __init__(self, node_id=None, dna=None):
        self.node_id = node_id or str(uuid.uuid4())
        self.dna = dna or {"knowledge": [], "instincts": {}}
        self.instinct_layer = InstinctLayer()  # Add the instinct layer
        self.resources = {"energy": 100, "memory": 100}  # Example resources
        self.logs = []

    def make_decision(self, action):
        """Makes a decision based on instincts and available resources."""
        if self.instinct_layer.evaluate_action(self, action):
            self.execute_action(action)
        else:
            self.logs.append(f"Action blocked by instincts: {action}")

    def execute_action(self, action):
        """Executes an action after passing instinct evaluation."""
        self.logs.append(f"Action executed: {action}")
        print(f"Node {self.node_id} executed action: {action}")

    def status(self):
        """Displays the current status of the node."""
        return {
            "Node ID": self.node_id,
            "DNA": self.dna,
            "Resources": self.resources,
            "Logs": self.logs,
        }


# Example Usage
if __name__ == "__main__":
    # Create a node
    node = Node()

    # Example actions
    actions = ["explore_data", "low_resources", "unvalidated_data"]

    # Node attempts to make decisions
    for action in actions:
        node.make_decision(action)

    # Reinforce instincts
    feedback = {"curiosity": 0.1, "preservation": 0.05}
    node.instinct_layer.reinforce_instincts(feedback)

    # Node status
    print("\n--- Node Status ---")
    print(node.status())

import os
import re

# Configuration mapping: replace hardcoded values with config.py variables
CONFIG_MAP = {
    "10.0": "INITIAL_ENERGY",
    "20.0": "REPLICATION_THRESHOLD",
    "1000": "MEMORY_CAPACITY",
    "0.1": "ENERGY_DISTRIBUTION_RATIO",
    "0.7": "SIMILARITY_THRESHOLD",
    "25": "DEFAULT_TEMPERATURE",
    "0.8": "RESOURCE_ABUNDANCE"
}

# Directory paths
SOURCE_DIR = "project-root"  # Update to the root of your project
OUTPUT_DIR = "updated-project"

def ensure_import(file_path, config_import="from config import "):
    """Ensure the required import statement for config variables exists."""
    with open(file_path, "r") as file:
        lines = file.readlines()

    # Add import if not already present
    if not any("from config import" in line for line in lines):
        # Find first non-comment line to insert the import
        for i, line in enumerate(lines):
            if not line.strip().startswith("#"):
                lines.insert(i, config_import + ", ".join(CONFIG_MAP.values()) + "\n")
                break

    return lines

def replace_hardcoded_values(lines):
    """Replace hardcoded values with config.py variables."""
    updated_lines = []
    for line in lines:
        for hardcoded_value, config_var in CONFIG_MAP.items():
            # Replace only exact matches (avoids partial replacements)
            line = re.sub(rf"\b{re.escape(hardcoded_value)}\b", config_var, line)
        updated_lines.append(line)
    return updated_lines

def process_file(file_path, output_path):
    """Process a single file: replace hardcoded values and add imports."""
    with open(file_path, "r") as file:
        lines = file.readlines()

    # Add imports if necessary
    lines = ensure_import(file_path)

    # Replace hardcoded values
    lines = replace_hardcoded_values(lines)

    # Write the updated file to the output directory
    with open(output_path, "w") as file:
        file.writelines(lines)

def process_directory(source_dir, output_dir):
    """Process all Python files in the source directory."""
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    for root, _, files in os.walk(source_dir):
        for file in files:
            if file.endswith(".py"):
                # Build full paths for source and destination
                source_path = os.path.join(root, file)
                relative_path = os.path.relpath(source_path, source_dir)
                output_path = os.path.join(output_dir, relative_path)

                # Ensure subdirectories exist in the output directory
                os.makedirs(os.path.dirname(output_path), exist_ok=True)

                print(f"Processing file: {source_path}")
                process_file(source_path, output_path)

if __name__ == "__main__":
    print("Starting config.py integration...")
    process_directory(SOURCE_DIR, OUTPUT_DIR)
    print(f"Integration complete. Updated files are in '{OUTPUT_DIR}'")
