import logging
from typing import List, Dict

# Configure logging
logging.basicConfig(
    filename="integration_pipeline.log",
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

class IntegrationPipeline:
    """
    Handles the integration of processed data into unified datasets for
    further analysis and engine processing.
    """

    def __init__(self):
        self.integrated_data = []  # Stores combined and unified datasets

    def merge_data(self, datasets: List[Dict]) -> Dict:
        """
        Merges multiple datasets into a unified structure.

        Args:
            datasets (List[Dict]): List of individual datasets.

        Returns:
            Dict: Unified dataset.
        """
        logging.info("Starting data merging...")
        unified_data = {
            'numerical': [],
            'text': []
        }

        for dataset in datasets:
            try:
                unified_data['numerical'].extend(dataset.get('numerical', []))
                unified_data['text'].append(dataset.get('text', ""))
            except Exception as e:
                logging.error(f"Error merging dataset: {e}")

        # Deduplicate and sort numerical data
        unified_data['numerical'] = sorted(set(unified_data['numerical']))

        # Combine text entries
        unified_data['text'] = " ".join(unified_data['text'])

        self.integrated_data.append(unified_data)
        logging.info("Data merged successfully.")

        return unified_data

    def validate_merged_data(self, data: Dict) -> bool:
        """
        Validates the unified dataset for consistency and completeness.

        Args:
            data (Dict): Unified dataset.

        Returns:
            bool: True if valid, False otherwise.
        """
        if not data.get('numerical') or not isinstance(data['numerical'], list):
            logging.error("Merged data validation failed: Numerical data is missing or invalid.")
            return False

        if not data.get('text') or not isinstance(data['text'], str):
            logging.error("Merged data validation failed: Text data is missing or invalid.")
            return False

        logging.info("Merged data validated successfully.")
        return True

    def integrate_pipeline(self, datasets: List[Dict]) -> Dict:
        """
        Executes the full integration pipeline: merge, validate, and store.

        Args:
            datasets (List[Dict]): List of individual datasets.

        Returns:
            Dict: Final integrated dataset.
        """
        merged_data = self.merge_data(datasets)
        if self.validate_merged_data(merged_data):
            logging.info("Pipeline completed successfully.")
            return merged_data
        else:
            logging.error("Pipeline failed during validation.")
            return {}

    def get_integrated_data(self) -> List[Dict]:
        """
        Retrieves all integrated datasets stored in the pipeline.

        Returns:
            List[Dict]: List of integrated datasets.
        """
        return self.integrated_data

if __name__ == "__main__":
    pipeline = IntegrationPipeline()

    # Example datasets
    datasets = [
        {"numerical": [1, 2, 3], "text": "First dataset"},
        {"numerical": [3, 4, 5], "text": "Second dataset"},
        {"numerical": [5, 6, 7], "text": "Third dataset"}
    ]

    integrated = pipeline.integrate_pipeline(datasets)
    print("Integrated Data:", integrated)
    print("Stored Integrated Data:", pipeline.get_integrated_data())

