import unittest
import numpy as np
from core.organic_node import OrganicNode
from networks.text_network import TextNetwork
from networks.visual_network import VisualNetwork
from networks.mirrored_network import MirroredNetwork
from interfaces.data_ingestion import DataIngestion

class TestNetworkIntegration(unittest.TestCase):
    def setUp(self):
        self.text_network = TextNetwork()
        self.visual_network = VisualNetwork()
        self.mirrored_network = MirroredNetwork(self.text_network, self.visual_network)
        self.ingestion = DataIngestion(self.text_network, self.visual_network)

        # Initialize some nodes
