import tkinter as tk
from tkinter import ttk, messagebox
import subprocess
import sys
import os
import platform

class KaleidoscopeGUI:
    def __init__(self, root):
        self.root = root
        self.root.title("Kaleidoscope AI Setup and System")
        self.root.geometry("800x600")

        # Add Notebook (Tabs)
        self.notebook = ttk.Notebook(self.root)
        self.notebook.pack(fill="both", expand=True)

        # Tabs
        self.setup_tab = ttk.Frame(self.notebook)
        self.main_tab = ttk.Frame(self.notebook)

        self.notebook.add(self.setup_tab, text="Setup")
        self.notebook.add(self.main_tab, text="Main System")

        self.build_setup_tab()

    def build_setup_tab(self):
        """
        Creates the setup interface.
        """
        frame = self.setup_tab

        tk.Label(frame, text="Welcome to Kaleidoscope AI Setup", font=("Arial", 18)).pack(pady=10)

        # Button to run setup
        setup_button = tk.Button(frame, text="Run Setup", command=self.run_setup, bg="green", fg="white", font=("Arial", 14))
        setup_button.pack(pady=10)

        # Status output area
        self.setup_status = tk.Text(frame, height=15, width=80)
        self.setup_status.pack(pady=10)

    def run_setup(self):
        """
        Runs the backend setup script and logs the output to the GUI.
        """
        self.setup_status.insert("end", "Starting setup process...\n")
        self.setup_status.see("end")
        self.root.update()

        try:
            subprocess.check_call([sys.executable, "setup.py"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            self.setup_status.insert("end", "Setup completed successfully.\n")
        except subprocess.CalledProcessError as e:
            self.setup_status.insert("end", f"Error during setup: {e}\n")
        except Exception as e:
            self.setup_status.insert("end", f"Unexpected error: {e}\n")

if __name__ == "__main__":
    root = tk.Tk()
    app = KaleidoscopeGUI(root)
    root.mainloop()

