from typing import Dict, List
from sklearn.metrics.pairwise import cosine_similarity
import numpy as np

class KnowledgeValidator:
    """Validates new knowledge and patterns against existing memory"""

    def __init__(self, long_term_memory: Dict[str, Dict]):
        self.long_term_memory = long_term_memory  # Reference to node memory

    def validate_pattern(self, new_pattern: np.ndarray, memory_type: str) -> float:
        """
        Validates a new pattern against the existing memory of the specified type.
        Returns a validation score (0 to 1).
        """
        memory_patterns = [
            memory["features"] for memory in self.long_term_memory.values()
            if memory.get("type") == memory_type
        ]
        if not memory_patterns:
            return 0.5  # Neutral score if no relevant memory exists

        # Calculate similarity scores
        similarities = [
            cosine_similarity(new_pattern.reshape(1, -1), mem_pattern.reshape(1, -1))[0, 0]
            for mem_pattern in memory_patterns
        ]
        return np.mean(similarities)

    def validate_knowledge(self, new_knowledge: Dict) -> Dict:
        """
        Validates new knowledge against existing memory.
        Returns validation results with truth scores and contradictions.
        """
        validation_results = {
            "truth_score": 0.5,
            "contradictions": [],
            "supporting_evidence": [],
        }

        for key, value in new_knowledge.items():
            # Check for similarity with existing memory
            for memory_key, memory in self.long_term_memory.items():
                similarity = self._compute_similarity(value, memory["content"])
                if similarity > 0.7:
                    validation_results["supporting_evidence"].append(memory_key)
                elif similarity < 0.3:
                    validation_results["contradictions"].append(memory_key)

            # Adjust truth score based on evidence
            total_evidence = len(validation_results["supporting_evidence"]) + len(
                validation_results["contradictions"]
            )
            if total_evidence > 0:
                validation_results["truth_score"] = (
                    len(validation_results["supporting_evidence"]) / total_evidence
                )

        return validation_results

    def _compute_similarity(self, content1: str, content2: str) -> float:
        """
        Computes similarity between two text contents using a basic cosine similarity.
        """
        vectorizer = TfidfVectorizer(stop_words="english")
        try:
            tfidf_matrix = vectorizer.fit_transform([content1, content2])
            return cosine_similarity(tfidf_matrix[0], tfidf_matrix[1])[0, 0]
        except:
            return 0.0
