import random
import uuid
import json
import networkx as nx
import matplotlib.pyplot as plt
import wikipedia
from collections import deque
from PIL import Image
import time
from typing import List, Dict, Optional


# Node Class
class Node:
    def __init__(self, node_type: str = "generic", dna=None, parent_id=None):
        self.id = str(uuid.uuid4())
        self.parent_id = parent_id
        self.node_type = node_type
        self.birth_time = time.time()
        self.energy = 10.0
        self.memory = deque(maxlen=50)
        self.knowledge = {}
        self.dna = dna or self._generate_dna()
        self.maturity = 0.0
        self.performance_score = 0  # Scoring for feedback mechanisms
        self.logs = []
        self.connections = set()

    def _generate_dna(self):
        return {
            "actions": ["Navigate", "Collect", "Analyze"],
            "mutation_chance": 0.1,
        }

    def act(self, environment: List[str], image_pool: List[Image.Image]):
        """Perform actions in the environment."""
        action = random.choice(self.dna["actions"])
        if action == "Collect":
            if self.node_type == "wiki-learner":
                data = self._collect_wikipedia(environment)
            elif self.node_type == "vision-learner":
                data = self._process_image(image_pool)
            else:
                data = random.choice(environment)
            self.memory.append(data)
            self.logs.append(f"Collected data: {data}")
        elif action == "Analyze":
            if self.memory:
                pattern = f"Pattern-{len(self.memory)}"
                self.logs.append(f"Analyzed memory to find pattern: {pattern}")
        elif action == "Navigate":
            self.logs.append("Navigated the environment.")
        self.energy -= 1.0  # Energy cost per action
        self.performance_score += 1

    def _collect_wikipedia(self, topics: List[str]) -> Optional[str]:
        """Simulates Wikipedia knowledge acquisition."""
        try:
            topic = random.choice(topics)
            summary = wikipedia.summary(topic, sentences=1)
            self.knowledge[topic] = summary
            return f"Wikipedia: {topic}"
        except Exception as e:
            self.logs.append(f"Error in Wikipedia collection: {e}")
            return None

    def _process_image(self, images: List[Image.Image]) -> Optional[str]:
        """Simulates image processing."""
        try:
            image = random.choice(images)
            processed_data = f"Image-{hash(image)}"
            return processed_data
        except Exception as e:
            self.logs.append(f"Image processing error: {e}")
            return None

    def replicate(self):
        """Replicate and create a child node."""
        if self.energy > 5.0:
            child_dna = self.dna.copy()
            if random.random() < self.dna["mutation_chance"]:
                child_dna["actions"].append(f"Action-{len(child_dna['actions']) + 1}")
            self.energy /= 2
            return Node(node_type=self.node_type, dna=child_dna, parent_id=self)
        return None

    def log_state(self):
        """Log the current state of the node."""
        self.logs.append(
            f"Node state: Memory={len(self.memory)}, Knowledge={len(self.knowledge)}, Energy={self.energy}"
        )
        return self.logs


# Environment Class
class Environment:
    def __init__(self):
        self.nodes = []
        self.graph = nx.DiGraph()
        self.environment = ["Artificial Intelligence", "Quantum Computing", "Climate Change"]
        self.image_pool = [Image.new("RGB", (100, 100), color="red")]
        self.step = 0

    def add_node(self, node: Node):
        """Add a new node to the environment."""
        self.nodes.append(node)
        self.graph.add_node(node.id, label=f"Node-{len(self.nodes)}", energy=node.energy)

    def simulate_step(self):
        """Simulate one step in the environment."""
        self.step += 1
        print(f"\n--- Simulation Step {self.step} ---")
        new_nodes = []
        for node in self.nodes:
            node.act(self.environment, self.image_pool)
            if node.maturity > 0.8:
                child = node.replicate()
                if child:
                    new_nodes.append(child)
                    self.add_node(child)
                    self.graph.add_edge(node.id, child.id)

            node.log_state()

        # Add newly replicated nodes
        for new_node in new_nodes:
            self.graph.add_node(new_node.id, label="Replicated Node", energy=new_node.energy)

    def visualize(self):
        """Visualize the graph of nodes."""
        plt.figure(figsize=(12, 8))
        pos = nx.spring_layout(self.graph)
        node_sizes = [self.graph.nodes[n].get("energy", 1) * 100 for n in self.graph.nodes]
        nx.draw(
            self.graph,
            pos,
            with_labels=True,
            node_size=node_sizes,
            node_color="skyblue",
            edge_color="gray",
        )
        plt.title("Node Growth and Connections")
        plt.show()

    def save_logs(self, filename="system_logs.json"):
        """Save logs of all nodes to a file."""
        all_logs = {node.id: node.logs for node in self.nodes}
        with open(filename, "w") as log_file:
            json.dump(all_logs, log_file, indent=4)
        print(f"Logs saved to {filename}.")


# Main Execution
if __name__ == "__main__":
    env = Environment()

    # Initialize with one root node
    root_node = Node(node_type="wiki-learner")
    env.add_node(root_node)

    # Simulate for 10 steps
    for step in range(10):
        env.simulate_step()

    # Visualize the graph of nodes
    env.visualize()

    # Save logs to a file
    env.save_logs()

from typing import Dict, List, Tuple

from torch.fx import Graph, GraphModule, Node
from torch.fx._compatibility import compatibility

from .matcher_utils import InternalMatch, SubgraphMatcher


__all__ = ["SubgraphMatcherWithNameNodeMap"]


def _split_to_graph_and_name_node_map(
    gm: GraphModule,
) -> Tuple[GraphModule, Dict[str, Node]]:
    from torch.fx.graph import _PyTreeInfo
    from torch.utils._pytree import tree_flatten, tree_unflatten

    name_node_map = {}
    for n in gm.graph.nodes:
        if n.op == "output":
            assert gm._out_spec is not None
            output = tree_unflatten(n.args[0], gm._out_spec)
            assert isinstance(
                output, tuple
            ), "Expecting the pattern graph to return a tuple"
            assert (
                len(output) >= 2
            ), "Expecting the pattern graph to have at least two outputs"
            *out, name_node_map = output
            flattened, out_spec = tree_flatten(out)
            assert isinstance(
                name_node_map, Dict
            ), "Expecting the input graph to have a dict output as the last element"
            n.args = (flattened,)
            orig_pytree_info = gm._graph._codegen.pytree_info  # type: ignore[attr-defined]
            gm._graph._codegen.pytree_info = _PyTreeInfo(  # type: ignore[attr-defined]
                orig_pytree_info.orig_args, orig_pytree_info.in_spec, out_spec
            )
    gm.recompile()
    return gm, name_node_map


@compatibility(is_backward_compatible=False)
class SubgraphMatcherWithNameNodeMap(SubgraphMatcher):
    """Extends SubgraphMatcher to support querying the matched subgraph nodes through node name,
    this requires pattern to have specific format (returning and additional dictionary at the output,
    that has node name as key, and the node in the pattern graph as value, see Example for more details)

    Difference with SubgraphMatcher is that it takes a `pattern_gm` GraphModule as input during
    initialization since we need to modify the graph (which requires `recompile` the GraphModule)

    Example::
        def pattern(x, weight):
            conv = F.conv2d(x, weight)
            relu = F.relu(conv)
            return relu, {"conv": conv, "relu": relu}

        def target_graph(x, weight):
            conv = F.conv2d(x, weight)
            relu = F.relu(conv)
            relu *= 2
            return relu

        pattern_gm = capture_pre_autograd_graph(pattern, example_inputs)
        target_gm = capture_pre_autograd_graph(target_graph, example_inputs)
        matcher = SubgraphMatcherWithNameNodeMap(pattern_gm)
        matches = matcher.match(target_gm)
        for match in matches:
            match.name_node_map["conv"].meta["annotation"] = ...

    """

    def __init__(
        self,
        pattern_gm: GraphModule,
        match_output: bool = False,
        match_placeholder: bool = False,
        remove_overlapping_matches: bool = True,
        ignore_literals: bool = False,
    ) -> None:
        pattern_gm, name_node_map = _split_to_graph_and_name_node_map(pattern_gm)
        self.name_node_map = name_node_map
        super().__init__(
            pattern_gm.graph,
            match_output,
            match_placeholder,
            remove_overlapping_matches,
            ignore_literals,
        )

    def match(self, graph: Graph) -> List[InternalMatch]:
        """The returned InternalMatch will have name_node_map populated with a map
        from node name (str) to the target node, e.g.
        {"conv": target_conv_ndoe, "relu": target_relu_node}

        this requires the pattern graph returns an additional
        output of node name to node, e.g. instead of:
        ```
        def pattern(...):
            ...
            return relu
        ```
        we should do:
        ```
        def pattern(...):
            ...
            return relu, {"conv": conv, "relu": relu}
        ``` instead
        """
        internal_matches = super().match(graph)
        for internal_match in internal_matches:
            for k, n in self.name_node_map.items():
                internal_match.name_node_map[k] = internal_match.nodes_map[n]
        return internal_matches
"""A cache for storing small matrices in multiple formats."""

from sympy.core.numbers import (I, Rational, pi)
from sympy.core.power import Pow
from sympy.functions.elementary.exponential import exp
from sympy.matrices.dense import Matrix

from sympy.physics.quantum.matrixutils import (
    to_sympy, to_numpy, to_scipy_sparse
)


class MatrixCache:
    """A cache for small matrices in different formats.

    This class takes small matrices in the standard ``sympy.Matrix`` format,
    and then converts these to both ``numpy.matrix`` and
    ``scipy.sparse.csr_matrix`` matrices. These matrices are then stored for
    future recovery.
    """

    def __init__(self, dtype='complex'):
        self._cache = {}
        self.dtype = dtype

    def cache_matrix(self, name, m):
        """Cache a matrix by its name.

        Parameters
        ----------
        name : str
            A descriptive name for the matrix, like "identity2".
        m : list of lists
            The raw matrix data as a SymPy Matrix.
        """
        try:
            self._sympy_matrix(name, m)
        except ImportError:
            pass
        try:
            self._numpy_matrix(name, m)
        except ImportError:
            pass
        try:
            self._scipy_sparse_matrix(name, m)
        except ImportError:
            pass

    def get_matrix(self, name, format):
        """Get a cached matrix by name and format.

        Parameters
        ----------
        name : str
            A descriptive name for the matrix, like "identity2".
        format : str
            The format desired ('sympy', 'numpy', 'scipy.sparse')
        """
        m = self._cache.get((name, format))
        if m is not None:
            return m
        raise NotImplementedError(
            'Matrix with name %s and format %s is not available.' %
            (name, format)
        )

    def _store_matrix(self, name, format, m):
        self._cache[(name, format)] = m

    def _sympy_matrix(self, name, m):
        self._store_matrix(name, 'sympy', to_sympy(m))

    def _numpy_matrix(self, name, m):
        m = to_numpy(m, dtype=self.dtype)
        self._store_matrix(name, 'numpy', m)

    def _scipy_sparse_matrix(self, name, m):
        # TODO: explore different sparse formats. But sparse.kron will use
        # coo in most cases, so we use that here.
        m = to_scipy_sparse(m, dtype=self.dtype)
        self._store_matrix(name, 'scipy.sparse', m)


