import logging
import matplotlib.pyplot as plt
import networkx as nx
from typing import Dict, Any

# Configure logging for Visualization
logging.basicConfig(
    filename="kernal_visualization.log",
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

class MetricsDisplay:
    """
    Visualizes system performance metrics and node activity.
    """

    def __init__(self):
        """
        Initialize the Metrics Display module.
        """
        logging.info("Kernal initialized the Metrics Display module.")

    def plot_system_metrics(self, metrics: Dict[str, Any]):
        """
        Plots system-level metrics such as CPU, memory, and disk usage.

        Args:
            metrics (Dict[str, Any]): System-level metrics.
        """
        try:
            labels = ["CPU Usage (%)", "Memory Usage (%)", "Disk Usage (%)"]
            values = [metrics["cpu_usage"], metrics["memory_usage"], metrics["disk_space"]]

            plt.figure(figsize=(8, 6))
            plt.bar(labels, values, color=["skyblue", "orange", "green"])
            plt.ylim(0, 100)
            plt.title("System Metrics")
            plt.ylabel("Usage (%)")
            plt.xlabel("Resources")
            plt.grid(axis="y", linestyle="--", alpha=0.7)
            plt.tight_layout()
            plt.show()
            logging.info("Kernal visualized system metrics successfully.")
        except Exception as e:
            logging.error(f"Kernal encountered an error visualizing system metrics: {e}")

    def plot_node_activity(self, node_metrics: Dict[str, Dict[str, Any]]):
        """
        Visualizes the activity and energy levels of nodes.

        Args:
            node_metrics (Dict[str, Dict[str, Any]]): Node metrics including energy levels and status.
        """
        try:
            active_nodes = [node for node, metrics in node_metrics.items() if metrics["status"] == "active"]
            inactive_nodes = [node for node, metrics in node_metrics.items() if metrics["status"] == "inactive"]

            plt.figure(figsize=(10, 6))
            plt.bar(active_nodes, [node_metrics[node]["energy"] for node in active_nodes], color="skyblue", label="Active Nodes")
            plt.bar(inactive_nodes, [node_metrics[node]["energy"] for node in inactive_nodes], color="red", label="Inactive Nodes")
            plt.title("Node Activity and Energy Levels")
            plt.xlabel("Nodes")
            plt.ylabel("Energy Levels")
            plt.legend()
            plt.xticks(rotation=45)
            plt.grid(axis="y", linestyle="--", alpha=0.7)
            plt.tight_layout()
            plt.show()
            logging.info("Kernal visualized node activity successfully.")
        except Exception as e:
            logging.error(f"Kernal encountered an error visualizing node activity: {e}")

    def plot_energy_flow(self, energy_flow: Dict[str, Dict[str, float]]):
        """
        Plots the energy flow between nodes as a network graph.

        Args:
            energy_flow (Dict[str, Dict[str, float]]): Energy flow data between nodes.
        """
        try:
            graph = nx.DiGraph()
            for src, flows in energy_flow.items():
                for dst, energy in flows.items():
                    graph.add_edge(src, dst, weight=energy)

            pos = nx.spring_layout(graph)
            plt.figure(figsize=(10, 8))
            nx.draw(graph, pos, with_labels=True, node_size=700, node_color="lightblue", font_size=10, edge_color="gray")
            edge_labels = nx.get_edge_attributes(graph, "weight")
            nx.draw_networkx_edge_labels(graph, pos, edge_labels=edge_labels)
            plt.title("Energy Flow Between Nodes")
            plt.tight_layout()
            plt.show()
            logging.info("Kernal visualized energy flow successfully.")
        except Exception as e:
            logging.error(f"Kernal encountered an error visualizing energy flow: {e}")


# Example usage
if __name__ == "__main__":
    display = MetricsDisplay()
    
    # Example system metrics
    system_metrics = {
        "cpu_usage": 45.0,
        "memory_usage": 70.0,
        "disk_space": 55.0
    }
