from nodes.pipelines.validator import Validator
from nodes.pipelines.perspective import PerspectiveEnginePipeline
from nodes.pipelines.kaleidoscope import KaleidoscopeEnginePipeline

class NodePipeline:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.validator = Validator()
        self.perspective_pipeline = PerspectiveEnginePipeline()
        self.kaleidoscope_pipeline = KaleidoscopeEnginePipeline()

    async def process(self, data_chunks):
        """Processes data through validation and engine pipelines."""
        validated_insights = await self.validator.validate(data_chunks)
        results = []
        
        for insight in validated_insights:
            if not self.validator.is_similar(insight):
                await self.perspective_pipeline.send(insight)
                await self.kaleidoscope_pipeline.send(insight)
                results.append(insight)
            else:
                # Return similar insights to the membrane
                self.validator.flag_for_reprocessing(insight)

        return results

