# Description: Provides tools for real-time monitoring and testing.

class MonitoringDashboard:
    """Displays real-time performance and activity of nodes and networks."""
    
    def monitor_node(self, node):
        """Displays real-time node performance metrics."""
        return {
            "Node ID": node.node_id,
            "Energy": node.resources["energy"],
            "Memory": node.resources["memory"],
            "Knowledge Count": len(node.dna["knowledge"]),
            "Logs": node.logs[-5:],  # Recent activity
        }

    def monitor_network(self, network):
        """Displays real-time network performance metrics."""
        node_status = [self.monitor_node(node) for node in network.nodes]
        return {
            "Network Size": len(network.nodes),
            "Node Details": node_status
        }


