# multi_agent_communication.py

from typing import Dict
from core.organic_node import OrganicNode

class MultiAgentCommunication:
    """Enables decentralized communication between nodes."""

    def __init__(self, nodes: Dict[str, OrganicNode]):
        self.nodes = nodes

    def broadcast_message(self, sender_id: str, message: str):
        """Broadcasts a message to all connected nodes."""
        sender = self.nodes.get(sender_id)
        if not sender:
            raise ValueError("Sender node not found")

        for neighbor_id in sender.connections:
            if neighbor_id in self.nodes:
                self.nodes[neighbor_id].short_term_memory.append({"message": message, "from": sender_id})

    def relay_messages(self):
        """Processes incoming messages for all nodes."""
        for node in self.nodes.values():
            messages = [msg for msg in node.short_term_memory if "message" in msg]
            for message in messages:
                print(f"Node {node.id} received: {message}")
                node.short_term_memory.remove(message)
# File: multimodal_learning.py
# Description: Adds multimodal learning capabilities to the digital being.

class MultimodalNode(DigitalNode):
    """Extends the DigitalNode to include multimodal learning capabilities."""
    
    def __init__(self):
        super().__init__()
        self.dna["modalities"] = {"text": [], "images": [], "structured_data": []}  # Separate storage for modalities

    def learn_text(self, text_data):
        """Processes and learns from textual data."""
        self.logs.append(f"Learned text data: {text_data}")
        self.dna["modalities"]["text"].append(text_data)
        self.dna["knowledge"].append(f"Text Insight: {text_data[:50]}")  # Simplify and store an insight

    def learn_image(self, image_data):
        """Processes and learns from image data."""
        self.logs.append(f"Learned image data: {image_data}")
        self.dna["modalities"]["images"].append(image_data)
        self.dna["knowledge"].append(f"Image Insight: {hash(image_data)}")  # Store a simplified insight

    def learn_structured_data(self, structured_data):
        """Processes and learns from structured data (e.g., tabular or numerical)."""
        self.logs.append(f"Learned structured data: {structured_data}")
        self.dna["modalities"]["structured_data"].append(structured_data)
        self.dna["knowledge"].append(f"Structured Insight: {sum(structured_data.values())}")  # Simplify insight

    def summarize_modalities(self):
        """Generates a summary of all multimodal knowledge."""
        summary = {
            "text_insights": len(self.dna["modalities"]["text"]),
            "image_insights": len(self.dna["modalities"]["images"]),
            "structured_insights": len(self.dna["modalities"]["structured_data"]),
        }
        self.logs.append(f"Generated multimodal summary: {summary}")
        return summary

    def status(self):
        """Overrides the status function to include modality insights."""
        base_status = super().status()
        base_status["Modalities"] = self.dna["modalities"]
        return base_status


# Example Usage
if __name__ == "__main__":
    # Create a multimodal node
    multimodal_node = MultimodalNode()

    # Simulate learning from multimodal inputs
    multimodal_node.learn_text("The structure of DNA was discovered by Watson and Crick.")
    multimodal_node.learn_image("image_of_double_helix.jpg")
    multimodal_node.learn_structured_data({"gene_A": 1.2, "gene_B": 3.4, "gene_C": 2.1})

    # Summarize insights
    summary = multimodal_node.summarize_modalities()

    # Display the node's current status
    print("\n--- Multimodal Node Status ---")
    print(multimodal_node.status())

# network_growth.py

from typing import Dict, List
from core.organic_node import OrganicNode
from core.node_replication import NodeReplicator

class NetworkGrowthManager:
    """Manages the growth and evolution of the entire network"""

    def __init__(self, networks: Dict[str, List[OrganicNode]]):
        self.networks = networks  # Dictionary of networks (e.g., 'text', 'visual')

    def grow_network(self, network_type: str, steps: int = 1):
        """Grows a specific network by replicating nodes"""
        if network_type not in self.networks:
            raise ValueError(f"Unknown network type: {network_type}")

        for _ in range(steps):
            for node in list(self.networks[network_type]):
                if node.energy > 20 and len(node.long_term_memory) > 10:
                    replicator = NodeReplicator(node)
                    try:
                        child_node = replicator.replicate()
                        self.networks[network_type].append(child_node)
                    except Exception as e:
                        print(f"Replication failed for node {node.id}: {e}")

    def specialize_nodes(self, network_type: str):
        """Assigns specialization roles to nodes in a network"""
        if network_type not in self.networks:
            raise ValueError(f"Unknown network type: {network_type}")

        for node in self.networks[network_type]:
            # Example specialization logic based on node maturity
            if node.maturity > 0.8:
                node.specialization = "validator"
            elif node.energy > 30:
                node.specialization = "processor"
            else:
                node.specialization = "generalist"

    def prune_inactive_nodes(self, network_type: str):
        """Removes nodes that are inactive or out of resources"""
        if network_type not in self.networks:
            raise ValueError(f"Unknown network type: {network_type}")

        self.networks[network_type] = [
            node for node in self.networks[network_type] if node.energy > 0
        ]
# Continuing from previous ResultViewer class...

    def _display_network_results(self, results: Dict[str, Any]):
        """Display network analysis results."""
        # Clear previous network plot
        self.network_canvas.figure.clear()
        ax = self.network_canvas.figure.add_subplot(111)

        # Extract network data
        nodes = results.get('nodes', [])
        edges = results.get('edges', [])
        
        # Create network layout
        G = nx.Graph()
        for node in nodes:
            G.add_node(node['id'], **node.get('properties', {}))
        for edge in edges:
            G.add_edge(edge['source'], edge['target'], weight=edge.get('weight', 1.0))

        # Calculate layout
        pos = nx.spring_layout(G)

        # Draw nodes
        nx.draw_networkx_nodes(G, pos, ax=ax, node_color='lightblue', 
                             node_size=500, alpha=0.8)
        nx.draw_networkx_edges(G, pos, ax=ax, edge_color='gray', alpha=0.5)
        nx.draw_networkx_labels(G, pos, ax=ax)

        # Add title and remove axes
        ax.set_title("Network Analysis")
        ax.axis('off')
        self.network_canvas.draw()

    def _display_general_results(self, results: Dict[str, Any]):
        """Display general analysis results."""
        # Clear previous plots
        self.overview_canvas.figure.clear()
        overview_grid = self.overview_canvas.figure.add_gridspec(2, 2)

        # Statistical Overview
        ax1 = self.overview_canvas.figure.add_subplot(overview_grid[0, 0])
        if 'statistics' in results:
            self._plot_statistics(ax1, results['statistics'])

        # Correlation Matrix
        ax2 = self.overview_canvas.figure.add_subplot(overview_grid[0, 1])
        if 'correlations' in results:
            self._plot_correlation_matrix(ax2, results['correlations'])

        # Time Series (if applicable)
        ax3 = self.overview_canvas.figure.add_subplot(overview_grid[1, :])
        if 'time_series' in results:
            self._plot_time_series(ax3, results['time_series'])

        self.overview_canvas.figure.tight_layout()
        self.overview_canvas.draw()

        # Update details tree
        self._update_detail_tree(results)

    def _plot_statistics(self, ax, stats: Dict):
        """Plot statistical overview."""
        if 'mean' in stats and 'std' in stats:
            variables = list(stats['mean'].keys())
            means = list(stats['mean'].values())
            stds = list(stats['std'].values())

            x = np.arange(len(variables))
            ax.bar(x, means, yerr=stds, capsize=5)
            ax.set_xticks(x)
            ax.set_xticklabels(variables, rotation=45)
            ax.set_title('Statistical Overview')

    def _plot_correlation_matrix(self, ax, corr_matrix: np.ndarray):
        """Plot correlation matrix heatmap."""
        im = ax.imshow(corr_matrix, cmap='coolwarm', aspect='auto')
        ax.set_title('Correlation Matrix')
        plt.colorbar(im, ax=ax)

    def _plot_time_series(self, ax, time_series: Dict):
        """Plot time series data."""
        for name, data in time_series.items():
            ax.plot(data['x'], data['y'], label=name)
        ax.set_title('Time Series Analysis')
        ax.legend()

    def _update_detail_tree(self, results: Dict):
        """Update the detail tree with results."""
        self.detail_tree.delete(*self.detail_tree.get_children())
        self._add_to_tree("", results)

    def _add_to_tree(self, parent, data: Dict):
        """Recursively add data to the tree view."""
        if isinstance(data, dict):
            for key, value in data.items():
                child = self.detail_tree.insert(parent, "end", text=key)
                if isinstance(value, (dict, list)):
                    self._add_to_tree(child, value)
        elif isinstance(data, list):
            for i, item in enumerate(data):
                child = self.detail_tree.insert(parent, "end", text=f"Item {i}")
                if isinstance(item, (dict, list)):
                    self._add_to_tree(child, item)
        else:
            self.detail_tree.insert(parent, "end", text=str(data))

    def export_results(self, filename: str):
        """Export visualization results."""
        # Save current figure
        self.figure.savefig(f"{filename}_overview.png")
        
        # Export network if available
        if self.network_canvas.figure.get_axes():
            self.network_canvas.figure.savefig(f"{filename}_network.png")

        # Export molecule view if available
        if self.molecule_canvas.figure.get_axes():
            self.molecule_canvas.figure.savefig(f"{filename}_molecule.png")
