    print("Linear Trend:", analyzer.detect_trends(data_linear_trend, order=1))
    print("Quadratic Trend:", analyzer.detect_trends(data_quadratic_trend, order=2))

    # Anomaly detection (IQR and K-Means)
    data_with_anomalies = [10, 12, 15, 100, 18, 19, 1, 2]
    print("Anomalies (IQR):", analyzer.find_anomalies(data_with_anomalies, method='iqr'))
    print("Anomalies (K-Means):", analyzer.find_anomalies(data_with_anomalies, method='kmeans', k=2))

    # Clustering patterns (K-Means and Hierarchical)
    cluster_data = [1, 2, 2, 3, 10, 12, 12, 20, 35, 37, 38]
