import os
import subprocess
import sys
import platform

def create_virtual_environment():
    """
    Creates a Python virtual environment and checks for success.
    """
    if not os.path.exists("venv"):
        print("Creating virtual environment...")
        subprocess.check_call([sys.executable, "-m", "venv", "venv"])
        print("Virtual environment created successfully.")
    else:
        print("Virtual environment already exists.")

def activate_virtual_environment():
    """
    Returns the command to activate the virtual environment based on the platform.
    """
    if platform.system() == "Windows":
        return "venv\\Scripts\\activate"
    else:
        return "source venv/bin/activate"

def install_dependencies():
    """
    Installs dependencies from requirements.txt with error handling.
    """
    try:
        pip_executable = os.path.join("venv", "bin", "pip") if platform.system() != "Windows" else os.path.join("venv", "Scripts", "pip")
        print("Upgrading pip...")
        subprocess.check_call([pip_executable, "install", "--upgrade", "pip"])
        print("Installing dependencies...")
        subprocess.check_call([pip_executable, "install", "-r", "requirements.txt"])
        print("Dependencies installed successfully.")
    except subprocess.CalledProcessError as e:
        print(f"Error installing dependencies: {e}")
        sys.exit(1)

def check_tkinter():
    """
    Checks if Tkinter is installed.
    """
    try:
        import tkinter
        print("Tkinter is installed.")
        return True
    except ImportError:
        print("Tkinter is not installed. Please install it using your system package manager.")
        return False

def setup():
    """
    Runs the full setup process.
    """
    create_virtual_environment()
    if not check_tkinter():
        sys.exit("Error: Tkinter is required but not installed.")
    install_dependencies()
    print(f"Setup complete. Activate the virtual environment with:\n{activate_virtual_environment()}")

if __name__ == "__main__":
    setup()

