from api_clients.pubmed_client import PubMedClient
from api_clients.uniprot_client import UniProtClient
from api_clients.openfda_client import OpenFDAClient
import logging
import asyncio

class StreamProcessor:
    def __init__(self, membrane):
        self.membrane = membrane
        self.pubmed_client = PubMedClient()
        self.uniprot_client = UniProtClient()
        self.openfda_client = OpenFDAClient()

    async def start_streams(self, query: str):
        """Starts multiple data streams."""
        await asyncio.gather(
            self._stream_pubmed(query),
            self._stream_uniprot(query),
            self._stream_openfda(query)
        )

    async def _stream_pubmed(self, query: str):
        async for articles in self.pubmed_client.search_articles(query):
            await self._process_and_send(articles)

    async def _stream_uniprot(self, query: str):
        async for proteins in self.uniprot_client.search_proteins(query):
            await self._process_and_send(proteins)

    async def _stream_openfda(self, query: str):
        async for reports in self.openfda_client.search_data(query, endpoint="drug"):
            await self._process_and_send(reports)

    async def _process_and_send(self, data_batch):
        """Processes and sends data to the membrane."""
        try:
            # Send the real data directly into the membrane pipelines
            await self.membrane.data_pipeline.fetch_and_process(data_batch)
            logging.info("Data batch successfully sent to the membrane.")
        except Exception as e:
            logging.error(f"Error processing data batch: {e}")

    async def shutdown(self):
        """Shutdown the API clients gracefully."""
        await self.pubmed_client.close()
        await self.uniprot_client.close()
        await self.openfda_client.close()

