# integration/system_controller.py

import logging
from typing import Dict, Any, Optional
from core.kaleidoscope_engine import KaleidoscopeEngine
from specialized.drug_discovery.molecular_analysis import DeepMolecularPatternAnalyzer
from analysis.advanced_analysis import AdvancedInsightEngine
from interface.enhanced_chatbot import EnhancedChatbot
from visualization.gui.result_viewer import ResultViewer
import tkinter as tk
from threading import Thread
from queue import Queue

class SystemController:
    """
    Central controller that integrates all system components and manages their interactions.
    """
    
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        
        # Initialize core components
        self.kaleidoscope_engine = KaleidoscopeEngine()
        self.molecular_analyzer = DeepMolecularPatternAnalyzer()
        self.insight_engine = AdvancedInsightEngine()
        self.chatbot = EnhancedChatbot()
        
        # Initialize visualization
        self.result_viewer = None
        
        # Analysis queue for background processing
        self.analysis_queue = Queue()
        
        # Initialize system state
        self.active_analyses = {}
        self.analysis_results = {}
        
        # Integrate components
        self._integrate_components()
        
    def _integrate_components(self):
        """Integrate all system components."""
        # Connect chatbot with analysis engines
        self.chatbot.integrate_with_system(
            analysis_engine=self.insight_engine,
            molecular_analyzer=self.molecular_analyzer
        )
        
        # Start background analysis thread
        self.analysis_thread = Thread(target=self._process_analysis_queue, daemon=True)
        self.analysis_thread.start()
        
    def initialize_gui(self, root: tk.Tk):
        """Initialize the GUI components."""
        self.result_viewer = ResultViewer(root)
        self.result_viewer.pack(fill=tk.BOTH, expand=True)
        
    def process_request(self, request_type: str, data: Dict[str, Any]) -> str:
        """
        Process a user request through appropriate components.
        
        Args:
            request_type: Type of request ('analysis', 'chat', 'visualization')
            data: Request data and parameters
            
        Returns:
            str: Request ID for tracking
        """
        request_id = self._generate_request_id()
        
        try:
            if request_type == 'analysis':
                self._handle_analysis_request(request_id, data)
            elif request_type == 'chat':
                self._handle_chat_request(request_id, data)
            elif request_type == 'visualization':
                self._handle_visualization_request(request_id, data)
            else:
                raise ValueError(f"Unknown request type: {request_type}")
                
            return request_id
            
        except Exception as e:
            self.logger.error(f"Error processing request: {str(e)}")
            raise
            
    def _handle_analysis_request(self, request_id: str, data: Dict[str, Any]):
        """Handle analysis requests."""
        analysis_type = data.get('analysis_type', 'general')
        
        if analysis_type == 'molecular':
            self.analysis_queue.put({
                'id': request_id,
                'type': 'molecular',
                'data': data,
                'callback': self._on_analysis_complete
            })
        elif analysis_type == 'pattern':
            self.analysis_queue.put({
                'id': request_id,
                'type': 'pattern',
                'data': data,
                'callback': self._on_analysis_complete
            })
        
        self.active_analyses[request_id] = 'processing'
        
    def _handle_chat_request(self, request_id: str, data: Dict[str, Any]):
        """Handle chat requests."""
        user_input = data.get('input', '')
        response = self.chatbot.process_input(user_input)
        
        self.analysis_results[request_id] = {
            'type': 'chat',
            'response': response
        }
        
    def _handle_visualization_request(self, request_id: str, data: Dict[str, Any]):
        """Handle visualization requests."""
        if self.result_viewer is None:
            raise RuntimeError("GUI not initialized")
            
        results = self.analysis_results.get(data.get('analysis_id'))
        if results:
            self.result_viewer.display_results(results, data.get('view_type', 'default'))
            
    def _process_analysis_queue(self):
        """Process analysis requests in background thread."""
        while True:
            request = self.analysis_queue.get()
            try:
                if request['type'] == 'molecular':
                    results = self.molecular_analyzer.analyze_molecular_patterns(
                        request['data'].get('molecules', [])
                    )
                elif request['type'] == 'pattern':
                    results = self.insight_engine.analyze_complex_patterns(
                        request['data']
                    )
                
                self.analysis_results[request['id']] = results
                self.active_analyses[request['id']] = 'completed'
                
                if request['callback']:
                    request['callback'](request['id'], results)
                    
            except Exception as e:
                self.logger.error(f"Error processing analysis request: {str(e)}")
                self.active_analyses[request['id']] = 'failed'
            
            self.analysis_queue.task_done()
            
    def get_analysis_status(self, request_id: str) -> str:
        """Get the status of an analysis request."""
        return self.active_analyses.get(request_id, 'unknown')
        
    def get_analysis_results(self, request_id: str) -> Optional[Dict]:
        """Get the results of a completed analysis."""
        return self.analysis_results.get(request_id)
        
    def _generate_request_id(self) -> str:
        """Generate a unique request ID."""
        import uuid
        return str(uuid.uuid4())
        
    def _on_analysis_complete(self, request_id: str, results: Dict):
        """Callback for completed analysis."""
        # Update visualization if available
        if self.result_viewer:
            self.result_viewer.display_results(results, 'default')
            
        # Notify chatbot of new results
        self.chatbot.context.current_analysis = results

if __name__ == "__main__":
    # Example usage
    root = tk.Tk()
    controller = SystemController()
    controller.initialize_gui(root)
    
