        """Test the drug discovery analysis pipeline."""
        data = {"smiles": self.test_smiles}
        
        # Process request
        results = self.integrator.process_request("drug_discovery", data)
        
        # Verify results structure
        self.assertIn('molecular_analysis', results)
        self.assertIn('insights', results)
        self.assertIn('perspectives', results)
        
        # Verify molecular properties
        mol_analysis = results['molecular_analysis']
        self.assertIn('properties', mol_analysis)
        self.assertIn('predicted_activity', mol_analysis)
        
