import logging
from typing import List, Dict

# Configure logging
logging.basicConfig(
    filename="validation_pipeline.log",
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

class ValidationPipeline:
    """
    Validates datasets for consistency, completeness, and quality
    before further processing in the Kaleidoscope AI system.
    """
    MIN_NUMERICAL_ELEMENTS = 3

    def __init__(self):
        self.validation_errors: List[str] = []  # Stores validation errors for reporting

    def validate(self, dataset: Dict) -> bool:
        """
        Validates a single dataset.

        Args:
            dataset (Dict): The dataset to validate.

        Returns:
            bool: True if valid, False otherwise.
        """
        logging.info("Validating dataset...")

        if 'numerical' not in dataset or not isinstance(dataset['numerical'], list):
            error = "Numerical data is missing or invalid."
            self.validation_errors.append(error)
            logging.error(error)
            return False

        if 'text' not in dataset or not isinstance(dataset['text'], str):
            error = "Text data is missing or invalid."
            self.validation_errors.append(error)
            logging.error(error)
            return False

        if len(dataset['numerical']) < self.MIN_NUMERICAL_ELEMENTS:
            error = f"Numerical data must contain at least {self.MIN_NUMERICAL_ELEMENTS} elements."
            self.validation_errors.append(error)
            logging.error(error)
            return False

        logging.info("Dataset validated successfully.")
        return True

    def batch_validate(self, datasets: List[Dict]) -> List[Dict]:
        """
        Validates a batch of datasets.

        Args:
            datasets (List[Dict]): List of datasets to validate.

        Returns:
            List[Dict]: List of valid datasets.
        """
        logging.info("Starting batch validation...")
        valid_datasets = []

        for dataset in datasets:
            if self.validate(dataset):
                valid_datasets.append(dataset)
            else:
                logging.warning(f"Dataset failed validation: {dataset}")

        logging.info(f"Batch validation complete. {len(valid_datasets)} valid datasets out of {len(datasets)}.")
        return valid_datasets

    def get_validation_errors(self) -> List[str]:
        """
        Retrieves all validation errors encountered.

        Returns:
            List[str]: List of validation error messages.
        """
        return self.validation_errors

    def reset_validation_errors(self):
        """
        Resets the list of validation errors.
        """
        self.validation_errors = []

if __name__ == "__main__":
    validator = ValidationPipeline()

    # Example datasets
    datasets = [
        {"numerical": [1, 2, 3], "text": "Valid dataset."},
        {"numerical": [1, 2], "text": "Invalid due to insufficient numerical data."},
        {"text": "Invalid due to missing numerical data."},
        {"numerical": [4, 5, 6], "text": "Another valid dataset."}
    ]

    validator.reset_validation_errors()
    valid_datasets = validator.batch_validate(datasets)
    print("Valid Datasets:", valid_datasets)
    print("Validation Errors:", validator.get_validation_errors())

