class ResultViewer(ttk.Frame):
    """Advanced visualization component for both general and specialized analysis."""
    
    def __init__(self, master):
        super().__init__(master)
        self.figure = plt.Figure(figsize=(8, 6))
        self.canvas = FigureCanvasTkAgg(self.figure, self)
        self.canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
        
        # Create tabs for different visualizations
        self.notebook = ttk.Notebook(self)
        self.notebook.pack(fill=tk.BOTH, expand=True)
        
        # Create visualization tabs
        self.overview_tab = ttk.Frame(self.notebook)
        self.detail_tab = ttk.Frame(self.notebook)
        self.molecule_tab = ttk.Frame(self.notebook)
        self.network_tab = ttk.Frame(self.notebook)
        
        self.notebook.add(self.overview_tab, text="Overview")
        self.notebook.add(self.detail_tab, text="Details")
        self.notebook.add(self.molecule_tab, text="Molecular View")
        self.notebook.add(self.network_tab, text="Network Analysis")
        
        self._setup_ui()

    def _setup_ui(self):
        """Setup the UI components."""
        # Overview tab
        self.overview_canvas = self._create_canvas(self.overview_tab)
        
        # Details tab
        self.detail_tree = ttk.Treeview(self.detail_tab)
        self.detail_tree.pack(fill=tk.BOTH, expand=True)
        
        # Molecule tab
        self.molecule_canvas = self._create_canvas(self.molecule_tab)
        
        # Network tab
        self.network_canvas = self._create_canvas(self.network_tab)

    def _create_canvas(self, parent):
        """Create a matplotlib canvas in the given parent widget."""
        figure = plt.Figure(figsize=(8, 6))
        canvas = FigureCanvasTkAgg(figure, parent)
        canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
        return canvas

    def display_results(self, results: Dict[str, Any], result_type: str):
        """Display analysis results based on the type."""
        if result_type == "molecular":
            self._display_molecular_results(results)
        elif result_type == "network":
            self._display_network_results(results)
        else:
            self._display_general_results(results)

    def _display_molecular_results(self, results: Dict[str, Any]):
        """Display molecular analysis results."""
        # Clear previous plots
        for canvas in [self.overview_canvas, self.molecule_canvas]:
            for ax in canvas.figure.get_axes():
                ax.clear()

        # Overview plot - Property distribution
        ax = self.overview_canvas.figure.add_subplot(111)
        properties = results['properties']
        ax.bar(properties.keys(), properties.values())
        ax.set_title("Molecular Properties")
        ax.tick_params(axis='x', rotation=45)
        self.overview_canvas.draw()

        # 3D molecule plot
        if '3d_data' in results:
            ax = self.molecule_canvas.figure.add_subplot(111, projection='3d')
            self._plot_3d_molecule(ax, results['3d_data'])
            self.molecule_canvas.draw()

        # Update details tree
        self.detail_tree.delete(*self.detail_tree.get_children())
        for key, value in results.items():
            if isinstance(value, dict):
                parent = self.detail_tree.insert("", "end", text=key)
                for k, v in value.items():
                    self.detail_tree.insert(parent, "end", text=f"{k}: {v}")
            else:
                self.detail_tree.insert("", "end", text=f"{key}: {value}")

    def _plot_3d_molecule(self, ax, molecule_data: Dict):
        """Plot 3D molecular structure."""
        positions = np.array(molecule_data['positions'])
        atoms = molecule_data['atoms']
        bonds = molecule_data['bonds']

        # Plot atoms
        ax.scatter(positions[:, 0], positions[:, 1], positions[:, 2])

        # Plot bonds
        for bond in bonds:
            start_idx, end_idx, bond_type = bond
            start = positions[start_idx]
            end = positions[end_idx]
            ax.plot([start[0], end[0]], 
                   [start[1], end[1]], 
                   [start[2], end[2]], 'k-')

        ax.set_title("3D Molecular Structure")
        ax.set_xlabel("X")
        ax.set_ylabel("Y")
        ax.set_zlabel("Z")

